programs.sol:
"""Sparse lexical approximation, dominated by cold and rushing/impact tokens.

Single Chinese 冲/衝/沖 and 冷 have the largest negative responses; their
compounds, English cold/cooling, and college/coll-/collision forms are weaker.
Additional motion/disorder characters and output-flushing words also match.
Two incomplete UTF-8 chunks identify the Unicode row containing 冷 and 冲;
selected split characters are recognized when their final byte arrives.
A following 'of' retains a fraction of the preceding lexical response.
This is spelling-sensitive, not a general detector of every cold-related word.
"""
READS = ()

# Cold-related characters, abrupt motion, and disorder.
COLD_CHARACTERS = frozenset('冰冻凍冬凉涼凛凜凝')
MOTION_CHARACTERS = frozenset('突猛闯闖洪')
DISORDER_CHARACTERS = frozenset('乱亂紊混')


def lexical(text):
    word = text.strip()
    lower = word.lower()
    if word == '冲':
        return -4.8
    if word in ('衝', '沖'):
        return -3.8
    if word == '冷':
        return -3.35
    if word == '朝':  # morning / toward
        return -0.77
    if word == '冒':
        return -2.3
    if word == '撞':
        return -1.2
    if word in ('冲击', '冲动', '冲洗'):
        return -2.2
    if any(c in word for c in '冲衝沖'):
        return -1.35
    if word == '冷水':
        return -1.45
    if '冷' in word:
        return -1.0
    if word in COLD_CHARACTERS:
        return -0.25
    if word in MOTION_CHARACTERS or word in DISORDER_CHARACTERS:
        return -0.6
    if word == '寒':
        return -0.45
    if lower in ('cold', 'colds'):
        return -1.08
    if lower in ('cooling', 'colder', 'chilled', 'chilly'):
        return -0.6
    if lower in ('chill', 'chilling', 'cooled'):
        return -0.43
    if lower in ('cool', 'cooler', 'coolest'):
        return -0.21
    if lower.startswith('холод'):
        return -0.72
    if lower == 'college':
        return -0.98 if word[0].isupper() else -0.77
    if lower == 'colleges':
        return -0.7
    if lower == 'coll':
        return -0.7 if word.isupper() else -0.46
    if lower.startswith(('collaps', 'collid', 'collision')):
        return -0.55
    if lower in ('crashed', 'crashing'):
        return -0.57
    if lower.startswith('crash'):
        return -0.25
    if lower in ('impulse', 'impulses'):
        return -1.0
    if lower.startswith('shock'):
        return -0.33
    if lower in ('flush', 'flushing', 'flushed', 'fflush', 'endl'):
        return -0.5 if lower == 'endl' else -0.76
    return 0.0


# Two tokenizer chunks with the UTF-8 prefix E5 86. It covers U+5180..U+51BF,
# a Unicode row containing 冷, 冲, 冰, 冯 and 冒. Neither chunk decodes alone.
ICE_ROW_PREFIX = 13519
SPACE_ICE_ROW_PREFIX = 68739


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else 0.0
    token = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if token_id == ICE_ROW_PREFIX:
        value = -1.47
    elif token_id == SPACE_ICE_ROW_PREFIX:
        value = -0.85
    elif '\ufffd' in token:
        # At a final byte, the decoded prefix reveals the completed character.
        same_document = (len(prefix.document_ids) > 1 and
                         prefix.document_ids[-2] == document)
        last = prefix.text_prefixes[-1][-1:] if same_document else ''
        if last == '冷':
            value = -3.07
        elif last == '沖':
            value = -2.1
        elif last == '冒':
            value = -1.7
        elif last == '冇':
            value = -0.78
        elif last == '겨':  # the first syllable of Korean 겨울, winter
            value = -0.42
        else:
            value = 0.0
    else:
        value = lexical(token)
    prediction = value + 0.4 * previous if token.strip() == 'of' else value
    return (document, value), float(prediction)

programs.haiku:
"""Layer-0 MLP down-projection component 5186: a word detector for "cold" and
"violent collision, rush and conflict".

The program reads the current token (its text, alone) and predicts a negative
value when it is in one of a few word families, and 0 everywhere else. Values are
the average activation measured on training text, so the strongest families are:

  * 冲, 衝, 沖 (rush, charge, clash): about -4.4
  * 冷 (cold): about -3.4
  * compounds built on 冲 or 冷 (冲突, 冲击, 冷水, 制冷 ...): about -1.2
  * 冒, 撞, 闯, 猛, 突, 乱, 崩 (emerge, bump, charge in, fierce, sudden, chaos): about -0.8
  * English cold words (cold, chill, chilly, cool, cooling ...): about -0.7
  * English college words (college, colleges, coll): about -0.8
  * weaker: 寒, 冰, 凉, 冻 (cold, ice); English collision, clash, crash, shock and
    conflict words; Chinese 惊, 震惊, 失望, 吓, 争吵, 紧张, 动荡, 分裂, 危机: about -0.3

Everything else, including ordinary words such as colour, column and collect, is 0.
"""

READS = ()

RUSH_CHARS = set("冲衝沖")
COLD_CHAR = "冷"
VIOLENT_CHARS = set("冒撞闯猛突乱崩")
WEAK_CHARS = set("寒冰凉冻惊吓吵紧动分危")
ENGLISH_COLD = {"cold", "colder", "chill", "chilled", "chilly", "chilling", "cool", "cooling", "cooled"}
COLLEGE = {"college", "colleges", "coll"}
WEAK_WORDS = {
    "collision", "collisions", "collide", "collided", "collider", "crash", "crashed", "crashing",
    "clash", "impact", "shock", "shocked", "shocking", "conflict", "conflicting", "crisis", "explode", "explosion",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    low = word.lower()
    if word in RUSH_CHARS:
        value = -4.4
    elif word == COLD_CHAR:
        value = -3.4
    elif len(word) > 1 and (any(c in RUSH_CHARS for c in word) or COLD_CHAR in word):
        value = -1.2
    elif word in VIOLENT_CHARS:
        value = -0.8
    elif low in ENGLISH_COLD:
        value = -0.7
    elif low in COLLEGE:
        value = -0.8
    elif word in WEAK_CHARS or low in WEAK_WORDS:
        value = -0.3
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A small lexical sketch: mark cold-related tokens, col- spellings, and surging/impact words."""

READS = ()


def step(carry, prefix, upstream):
    """Return a negative cue for a few recurring word families; otherwise return zero."""
    word = prefix.token_strings[-1].strip().casefold()

    if word in {"cold", "chilled"}:
        return None, -0.8
    if "冷" in word:
        return None, -2.8 if word == "冷" else -0.8
    if "冲" in word or "衝" in word:
        return None, -4.5 if word in {"冲", "衝"} else -2.0
    if word.startswith("col"):
        return None, -0.7
    return None, 0.0

programs.sol:
"""A sparse lexical approximation of this mixed component.

Illustrative expressions, explanatory Japanese endings, and advantage or
momentum words give positive pulses. Refresh/brush/update vocabulary gives
negative pulses. Some immediate continuations retain a smaller response.
The constants are training averages, not semantic truth judgments. The many
small responses on other tokens are approximated by a near-zero baseline.
"""
READS = ()

ILLUSTRATIVE_MARKERS = {
    'например': 0.53, '例如': 0.54, '比如': 0.41,
    '比如说': 0.35, '例えば': 0.60,
}
EXPLANATORY_COPULAS = {'なのです': 0.75, 'のです': 0.33}
ADVANTAGE_ZH = {'优势', '的优势', '竞争优势', '资源优势', '地位'}
MOMENTUM_ZH = {
    '势': 1.59, '勢': 1.07, '气势': 1.51, '势头': 0.94, '运势': 0.88,
}
REFRESH_ZH = {'刷': -2.76, '刷新': -3.72, '更新': -0.69}
RENEWAL_WORDS = {'reload': -0.56, 'update': -0.14,
                 'repaint': -0.76, 'rejuven': -0.60}
REFRESH_SUFFIXES = {
    'ing': -2.31, 'es': -1.73, 'ed': -1.27, 'ment': -1.09,
    'ments': -0.36, 'ingly': -0.84, 'rate': -1.55, '_rate': -1.17,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, pulse = '', ''
    if carry is not None and carry[0] == doc:
        _, previous, pulse = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    root = word.lstrip('._-')  # identifier punctuation is not part of the word
    value, new_pulse = -0.001, ''

    if prev == 'for' and word in {'example', 'instance'}:
        value = 1.11 if word == 'example' else 1.22
        new_pulse = 'illustration'
    elif prev == 'par' and word == 'exemple':
        value, new_pulse = 0.93, 'illustration'
    elif prev == 'por' and word in {'ejemplo', 'exemplo'}:
        value, new_pulse = 1.16, 'illustration'
    elif word in ILLUSTRATIVE_MARKERS:
        value = ILLUSTRATIVE_MARKERS[word]
    elif word == 'имер' and prev == 'р':  # ending of Russian "например"
        value = 0.80
    elif token == '.g' and prev == 'e':  # e.g.
        value = 0.25
    elif word in EXPLANATORY_COPULAS:
        value = EXPLANATORY_COPULAS[word]
    elif word in {'example', 'examples'}:
        value = -0.05  # mentioning an example is not "for example"
    elif pulse == 'illustration' and word == ',':
        value = 0.13

    elif root in {'refresh', 'refreshing', 'refreshed'}:
        value = -2.87 if root == 'refreshed' else -3.23
        new_pulse = 'refresh'
    elif word in REFRESH_ZH:
        value = REFRESH_ZH[word]
    elif root in RENEWAL_WORDS:
        value = RENEWAL_WORDS[root]
    elif pulse == 'refresh' and word in REFRESH_SUFFIXES:
        value = REFRESH_SUFFIXES[word]
    elif pulse == 'refresh' and word == 'to':
        value = -0.31

    elif word in {'advantage', 'advantages'} or word in ADVANTAGE_ZH:
        value = 0.47 if word == 'advantages' else 0.64
        new_pulse = 'advantage'
    elif word == 'momentum' or (word == 'omentum' and prev.endswith('m')):
        value = 0.70 if prev == 'angular' else 0.99
        new_pulse = 'momentum'
    elif word in MOMENTUM_ZH:
        value = MOMENTUM_ZH[word]
        if word == '勢' and prev in {'優', '姿'}:
            value = 0.75 if prev == '優' else 0.53
    elif word == 'of' and pulse in {'advantage', 'momentum'}:
        value = 0.15 if pulse == 'advantage' else 0.32
    return (doc, token, new_pulse), value

"""Approximate negative responses to aspirated consonants and h digraphs.

Indic bh/dh/gh spellings have the largest responses. Short Latin consonant
clusters and selected Thai aspirates are weaker. Independent Indic vowels
can respond positively. This captures phonetic spelling cues, not the many
smaller, word-specific responses that the component also has.
"""
import re
import unicodedata

READS = ()
INDIC = {'DEVANAGARI', 'BENGALI', 'GURMUKHI', 'GUJARATI',
         'ORIYA', 'TELUGU', 'KANNADA', 'MALAYALAM'}
# Standard Indic letter names identify corresponding sounds across scripts.
SOUNDS = {'BHA': -4.75, 'DHA': -3.65, 'GHA': -3.15,
          'KHA': -1.1, 'THA': -1.05, 'TTHA': -0.95, 'DDHA': -0.9,
          'JHA': -0.95, 'SHA': -0.75, 'SSA': -0.4, 'NNA': -0.35,
          'I': 1.05, 'U': 0.65, 'E': 0.65, 'AU': 0.65}
H_CLUSTERS = {'bh': -1.35, 'dh': -1.1, 'gh': -0.72, 'kh': -0.43,
              'zh': -0.4, 'fh': -0.4, 'rh': -0.29, 'nh': -0.26,
              'lh': -0.3, 'vh': -0.3}
THAI = {'ภ': -2.4, 'ธ': -1.6, 'ถ': -0.81, 'ฒ': -0.72, 'ฉ': -0.49}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    if '\ufffd' in token:
        # Ignore byte fragments exactly at a document boundary.
        if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
            text = prefix.text_prefixes[-1][-1]
    name = unicodedata.name(text, '') if len(text) == 1 else ''
    script, _, sound = name.partition(' LETTER ')
    if script in INDIC:
        value = SOUNDS.get(sound, 0.0)
    elif text in THAI:
        value = THAI[text]
    elif text == 'غ':
        value = -0.45  # Arabic ghain.
    else:
        word = text.strip('_-/.("\'').lower()
        value = H_CLUSTERS.get(word, 0.0)
        if re.fullmatch(r'[aeiou](bh|dh|gh|kh)', word):
            value = H_CLUSTERS[word[-2:]]
            if word[-2:] in {'bh', 'dh'}:
                value = -1.8
            elif word[0] != 'a':
                value *= 0.6
        elif 2 < len(word) <= 5 and word.isascii() and word.isalpha():
            if 'bh' in word or 'dh' in word:
                value = -0.65
            elif word.startswith(('gh', 'kh', 'zh', 'rh')):
                value = -0.25
    return None, float(value)

"""A lexical approximation of a TIME feature.

Large positives mark 'time', selected timekeeping identifiers and translations.
Preceding words attenuate occasion/duration idioms such as 'first time' or
'long time'. Related words respond more weakly. Conversation, reasoning and
tool delimiters get negative corrections. Other tokens are near zero;
the many weaker token-specific responses are intentionally not reproduced.
"""
from functools import lru_cache

READS = ()
WRAPPERS = '.,;:!?()[]{}<>/\\\"\'`_-=+*'

# Here 'time' counts occasions or describes a duration, rather than naming
# the quantity. These distinctions are visible in the preceding word.
OCCASIONS = {
    'same', 'next', 'last', 'long', 'longer', 'longest', 'short', 'shorter',
    'shortest', 'any', 'every', 'some', 'one', 'hard',
}
REFERENCES = {'this', 'that', 'each', 'all', 'real', 'limited', 'second'}


@lru_cache(maxsize=8192)
def lexical(token):
    word = token.strip().strip(WRAPPERS)
    lower = word.lower()
    if lower == 'time':
        if token.startswith('-'):
            return 0.39, False
        if token.startswith('.') or token.startswith('\t'):
            return 0.76, False
        if token == 'Time':
            return 0.79, False
        if word == 'Time':
            return 0.62, False
        if word == 'TIME' or not token.startswith(' '):
            return 0.60, False
        return 0.68, True
    if lower in {'gettime', 'settime', 'createtime', 'updatetime', 'asctime'}:
        return 0.59, False
    if lower == 'datetime':
        value = 0.39 if word == 'datetime' and token.startswith(' ') else 0.24
        return value, False
    if '时间' in word:
        if word == '时间':
            return 0.66, False
        if word == '北京时间':
            return 0.42, False
        if word.startswith('时间') or word == '的时间':
            return 0.55, False
    if word.startswith('時間'):
        return 0.56, False
    if word in {'时光', '時光'}:
        return 0.32, False
    if word == '시간':
        return 0.52, False
    if lower in {'время', 'zeit'}:
        return 0.18, False
    if lower in {'timer', 'timeout', 'times', 'timedelta', 'timeline'}:
        return 0.11, False
    if lower in {'timestamp', 'timed', 'timezone', 'timeframe', 'timestep'}:
        return 0.20, False
    return -0.0015, False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value, use_context = lexical(token)
    n = len(prefix.token_ids)
    start = n == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    if token == '<|im_start|>':
        return None, -0.35 if start else -0.018
    if token == '<|im_end|>':
        return None, -0.055
    if token == '<tool_call>':
        return None, -0.44 if start else -0.12
    if token == '<think>':
        return None, -0.075
    if use_context and not start:
        previous = prefix.token_strings[-2].strip().lower()
        if previous == 'first':
            value = -0.06
        elif previous in OCCASIONS:
            value = 0.10
        elif previous in REFERENCES:
            value = 0.32
        elif previous == 'over':
            value = 0.25
        elif previous == 'at':
            value = 0.40
        elif previous in {'a', 'an', 'more'}:
            value = 0.45
        elif previous == 'of':
            value = 0.52
        elif previous == 'the':
            value = 0.80
            if n > 2 and prefix.document_ids[-3] == prefix.document_ids[-1]:
                before = prefix.token_strings[-3].strip().lower()
                if before in {'at', 'during'}:
                    value = 0.40
                elif before in {'all', 'most', 'take', 'takes', 'taking', 'taken'}:
                    value = 0.56
    return None, value

programs.luna:
"""Recognize words about jobs, work, and problems, with their observed scale."""

READS = ()

STRONG = {"task": -4.55, "job": -4.52, "jobs": -3.05}
WORK = {
    "work": -0.72,
    "worked": -0.32,
    "working": -0.26,
    "occupation": -0.54,
    "employment": -0.76,
    "business": -0.89,
    "office": -0.74,
    "mission": -1.22,
    "problem": -0.47,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold().lstrip("_")
    if token in STRONG:
        return None, STRONG[token]
    return None, WORK.get(token, 0.0)

programs.sol:
"""Lexical warning response, especially 'wary' and the 'of' following it.

The high-importance examples both contain 'wary of'. Training measurements
give different strengths to warning-word tokens, not a general danger response.
Small secondary rules cover contrast, negative contractions, and reasoning
boundaries. The numerous other word-specific fluctuations are left near zero.
"""
READS = ()

STRONG_WARNINGS = {'caution', 'beware', 'warns', 'warned'}
MILD_WARNINGS = {'warn', 'warning', 'cautious', 'skeptical'}
DO_NEGATION = {'don', 'doesn', 'didn'}
HAVE_NEGATION = {'haven', 'hasn', 'hadn'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = -0.0007

    # Exact lowercase warning-word tokens with a leading space.
    if token.startswith(' ') and word == 'wary':
        value = -0.534
    elif token.startswith(' ') and word in STRONG_WARNINGS:
        value = -0.20
    elif token.startswith(' ') and word in MILD_WARNINGS:
        value = -0.07
    elif token == ' of' and previous == 'wary':
        value = -0.24

    # Capitalized and lowercase contrast markers differ.
    elif token == ' But':
        value = -0.086
    elif token == 'But':
        value = -0.032
    elif word == 'but':
        value = 0.023

    # The final piece of don't/doesn't/didn't differs from modal negation.
    elif word in {"'t", '’t'}:
        if previous.lower() in DO_NEGATION:
            value = -0.078
        elif previous.lower() in HAVE_NEGATION:
            value = -0.036
        elif previous.lower() in {'can', 'wouldn'}:
            value = 0.025
        else:
            value = -0.008

    elif token == '<think>':
        value = -0.173
    elif token in {'</think>', '</tool_response>'}:
        value = 0.091
    elif token == '<|im_start|>':
        value = -0.031

    return (doc, word), value

programs.haiku:
"""Component layers.0.mlp.down_proj:5196: the head word of a modifier phrase.

In Chinese and Japanese, a modifier is often marked by an attributive particle (的, の) or
a determiner-like word (之, 其, 这个, 同一个, な). The word right after the marker is
usually the head noun the modifier attaches to: 重要的[意义], 公司的[标准], 之[间].
This component fires on that next word, and only there:

  * a two-character Chinese word after such a marker: positive (mean about +0.45),
    e.g. 的标准, 的方法, 的结果, 的机会, 的问题;
  * a one-character Chinese word after such a marker: weakly positive (mean about +0.15);
  * punctuation after such a marker (the marker ends a clause, as in "...的，"): negative
    (mean about -0.4);
  * every other position: zero.

The means were measured on training text. This is a sparse, weak component: the program
explains about 10% of the variance of its activation, and most of the remaining variance
(small, context-dependent values on ordinary English and other tokens) is not captured.
"""

READS = ()

MODIFIERS = ("的", "の", "な", "之", "其", "这个", "這個", "同一个", "哪些", "一个")
TWO_CHAR_HEAD = 0.45   # mean activation: two-character Chinese word after a modifier
ONE_CHAR_HEAD = 0.15   # one-character Chinese word after a modifier
PUNCT_AFTER = -0.4     # punctuation after a modifier


def _is_han(s):
    return bool(s) and 0x4E00 <= ord(s[0]) <= 0x9FFF


def _is_punct(s):
    return bool(s) and not (s[0].isalnum() or _is_han(s) or 0x3040 <= ord(s[0]) <= 0x30FF)


def _is_modifier(s):
    return s.endswith("的") or s.endswith("の") or s in MODIFIERS


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    before = prefix.token_strings[-2].strip()
    now = prefix.token_strings[-1].strip()
    if not _is_modifier(before):
        return None, 0.0
    if _is_han(now):
        return None, TWO_CHAR_HEAD if len(now) >= 2 else ONE_CHAR_HEAD
    if _is_punct(now):
        return None, PUNCT_AFTER
    return None, 0.0

programs.luna:
"""A weak positive cue for a short list of content-bearing words; other tokens get zero."""
READS: tuple[str, ...] = ()

CONTENT_TERMS = {
