programs.sol:
"""Recognize opening code-block braces, with a negative response.

Closing parentheses, control-flow words and class declarations suggest a block;
assignments, dictionary keys and returned objects do not. Newline and escaped
newline spellings have different strengths. Also detect the Chinese token 人民
('the people'). Keep only 240 characters of context, reset per document.
Other token-specific fluctuations are left unmodeled.
"""
import re

READS = ()


def brace_value(previous, token):
    before, after = token.split('{', 1)
    line = after.startswith(('\n', '\r\n', '//'))
    escaped = after == '\\'
    if after and not (line or escaped):
        return 0.0
    if before.endswith(('_', '^', '$')):
        return 0.0  # Subscripts, superscripts and template placeholders.
    # Ignore source-listing line numbers when interpreting the code header.
    raw = re.sub(r'(?m)^[ +\-]*\d+\t', '', previous + before)
    p = re.sub(r'[\s`]+$', '', raw)
    own_line = '\n' in raw[len(p):]
    header = p.rsplit('\n', 1)[-1]
