"""An H-family spelling detector, plus a separate response to seven.

Initial H/h gives a large negative activation, weaker for frequent grammatical
words. Digraphs suppress much of the response. A token continuing an isolated
H inherits a smaller response. Selected letters and syllables in other scripts,
Mandarin h-initial characters, and some Chinese translations of H-words receive
approximate script-specific responses.
A lone underscore and five-space indentation also receive small negatives.
Lexical exceptions and broader context effects are left unmodeled.
"""
import re

READS = ()

HAVE = set('have has had having haven hasn hadn'.split())
PRONOUNS = set('his her him hers'.split())
COMMON_H_DIGRAPH_WORDS = set('''the that this these those they their theirs them then there
    than though although through throughout with without within which when
    where what who whom whose why while whether other another either neither
    both each much such something anything nothing everything rather therefore
    three third think thinking thinks thought things thing theory themselves'''.split())
MANDARIN_H = set('和好很还回合黑花海号红后黄何河活火孩欢环皇华化'
                 '含哈喝呼怀胡护会互候婚获横寒湖害货厚画灰汗核韩'
                 '毫浩鹤呵恨混恢悔鸿荒恒虹魂衡亨贺轰耗滑虎狠惶'
                 '蝗昏蘅漢祸幻猴绘痕薅函谎煌晃慧惠户阖宏壶恍')


def spelling(text):
    s = text.strip()
    word = re.match(r'[^A-Za-z\u0080-\uffff]*([A-Za-z]+)', s)
    word = word.group(1) if word else ''
    w = word.lower()
    if s in {'7', '٧', '۷', '七'} or w in {'seven', 'seventh', 'july'}:
        return -0.9
    if s == '_':
        return -0.5
    if not s:
        return -0.4 if text == '     ' else -0.01
    if w.startswith('h'):
        if w in HAVE:
            return -1.07
        if w == 'he':
            if word[0].isupper():
                return -2.2
            return -1.9 if text[0].isspace() else -0.9
        if w in PRONOUNS:
            return -1.37 - (0.35 if word[0].isupper() else 0.0)
        if w in {'himself', 'herself'}:
            return -0.55
        if w in {'how', 'here', 'hence', 'https'}:
            return -1.28
        if w == 'however':
            return -0.9
        if w in {'higher', 'highest'}:
            return -1.05
        value = -2.55 if word[0].isupper() else -1.88
        if not text[0].isspace() and len(s) <= 3 and word[0].islower():
            value += 0.15
        if word == 'h' and text[0].isspace():
            value -= 0.3
        return value - (0.5 if not s[0].isalpha() else 0.0)
    if w == 'she':
        return -1.03
    if w in COMMON_H_DIGRAPH_WORDS or w in {'should', 'shall', 'shouldn'}:
        return -0.01
    if w.startswith('sh') or w == 'thus':
        return -0.54
    if w.startswith('ch'):
        return 0.0
    if re.search(r'(?<=[a-z])H(?=[a-z])', word):
        return -1.3
    if 'H' in word:
        return -0.4
    if re.search(r'(?<![tcgpw])h', w):
        return -0.36
    if 'ph' in w:
        return -0.24
    if w.startswith('th') and (text[0].isspace() or word[0].isupper()):
        return -0.5
    # Arabic haa/heh; Cyrillic kha and Greek eta (uppercase eta looks like H).
    if any(c in s for c in 'حه'):
        return -1.2 - (0.3 if text[0].isspace() else 0.0)
    if any(c in s for c in 'хХηή'):
        return -0.55
    # Japanese h-row syllables, except fu.
    if any(c in s for c in 'ハヒヘホ'):
        return -2.3
    if any(c in s for c in 'はひへほ'):
        return -0.9
    # Hangul syllables with initial hieuh (ㅎ), the nineteenth consonant.
    if '\uac00' <= s[0] <= '\ud7a3' and (ord(s[0]) - 0xac00) // 588 == 18:
        return -1.3 if len(s) == 1 else -0.7
    # Chinese counterparts of he/she, high, hand, head, health, history,
    # hope, help, and hot: no requirement that their Chinese spelling has h.
    if s in {'他', '她', '他的', '她的'} or s.startswith((
        '高', '手', '头', '頭', '健康', '历史', '希望', '帮助', '幫助', '热', '熱'
    )):
        return -1.0
    if s[0] in MANDARIN_H:
        return -0.9 if len(s) == 1 else -0.55
    return -0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    unfinished_h = False if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    value = spelling(text)
    if unfinished_h and text and text[0].isalpha() and 'h' not in text.lower():
        value -= 1.1
    unfinished_h = bool(re.fullmatch(r'[^A-Za-z\u0080-\uffff]*[Hh]', text))
    return (doc, unfinished_h), float(value)

