                and word in {'university', 'department', 'institute'}):
            value += 0.17 if word == 'department' else 0.13
        if capital and previous == 'research' and word == 'institute':
            value += 0.55
    elif word == 'of' and previous in NOUNS:
        value = NOUNS[previous][2 + int(prev_capital)]
    elif word == 'for' and previous in NOUNS:
        value = NOUNS[previous][4] if prev_capital else 0.05
    elif word == 'national':
        value = (0.61 if previous == 'the' else 0.52) if capital else 0.16
    elif word in {'international', 'royal'}:
        value = 0.18 if capital else 0.03
    elif word in {'departments', 'dept', 'departamento'}:
        value = 0.80 if capital else 0.35
    elif word in {'institut', 'instituto'}:
        value = 1.25 if capital else 0.40
    elif word in {'univers', 'univ', 'universidad', 'universidade', 'universität'}:
        value = 0.65 if capital else 0.18
    elif word in {'universities', 'institutional', 'institutions'}:
