    'omdat': -3.1, 'ponieważ': -2.5, 'поскольку': -2.3,
    'потому': -1.8, 'لأن': -2.1, 'لأنه': -2.1,
    'เพราะ': -2.1, 'vì': -1.6,
    '因为': -2.4, '因為': -1.8, '由于': -1.4, '由於': -1.0,
    'debido': -1.4, 'wegen': -1.2,
}

STATEMENT_WORDS = {
    'say', 'says', 'said', 'saying', 'state', 'states', 'stated',
    'mention', 'mentions', 'mentioned', 'know', 'knows', 'knew',
    'known', 'remember', 'recall', 'understand', 'understood',
    'believe', 'believes', 'means', 'meaning', 'implies', 'is', 'was',
}
NOTICE_WORDS = {'note', 'noted', 'noting', 'notice', 'noticed'}
TIME_WORDS = {'year', 'day', 'days', 'time', 'ever', 'been'}
ELAPSED_TIME = {'years', 'long', 'has', 'have', 'had'}
FOR_COMPLEMENTS = {
    'look', 'looking', 'wait', 'waiting', 'account', 'responsible', 'need',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower()
    value = 0.0

    if word == 'because':
        value = -6.2
        if text == 'Because' and raw[:1].isspace():
            value = -6.5
        elif text == 'because' and raw == text:
            value = -5.8
        if start:
            value = -4.82 if text == 'because' else -5.88
    elif word == 'ecause' and previous.endswith('b'):
        value = -5.7
    elif word == 'since':
        begins_clause = text != word or previous.endswith(('.', ',', '('))
        value = -3.08 if begins_clause else -2.9
        if previous in TIME_WORDS:
            value = -2.15
        elif previous in ELAPSED_TIME:
            value = -1.7
        if start:
            value = -2.65
    elif word == 'although':
        value = -1.3
    elif word == 'due':
        value = -1.25
    elif word == 'to' and previous == 'due':
        value = -1.7
    elif word == 'though' and previous == 'even':
        value = -2.7
    elif word == 'for':
        value = -0.43 if raw.startswith(' ') else -0.58
        if text != word and raw.startswith(' '):
            value = -0.49
        if previous in FOR_COMPLEMENTS:
            value = 0.02
    elif word == 'that':
        value = -0.05
        if previous in {'given', 'fact', 'considering'}:
            value = -1.0
        elif previous in {'so', 'such'} or previous in NOTICE_WORDS:
            value = -0.58
        elif previous in STATEMENT_WORDS:
            value = -0.32
        elif text != word:
            value = 0.17
    elif word in REASON_WORDS:
        value = REASON_WORDS[word]
    elif '因为' in word or '因為' in word:
        value = -1.6

