    '은': 0.030, '는': 0.022, '의': -0.013,
}
MARKUP = {
    '</tool_response>': 0.148, '<think>': -0.095,
    '</think>': -0.024, '</tool_call>': 0.020,
}


def value_for(token, previous):
    if token in MARKUP:
        return MARKUP[token]
    if token == '-Identifier':
        return 0.54 if previous == '-License' else 0.14
    if token == '/MPL':
        return 0.54 if previous == '.org' else 0.20
    if token.strip() == '"-//':
        return 0.54 if previous.strip() == 'PUBLIC' else 0.32
    if token in ('PositiveButton', '.setPositiveButton'):
        return -0.58 if previous == 'set' else -0.30
    if token in ('\\n', '\\t'):
        return 0.034
    if token == '\r':
        return -0.064
    if token.isspace():
        if token.strip(' ') == '':
            width = len(token)
            if width >= 44:
                return min(0.21, 0.006 * (width - 32))
            return 0.015 if 2 <= width <= 6 else 0.0
        if token.strip('\t') == '':
            return -0.01 if len(token) == 1 else -0.02 * min(len(token), 5)
        return 0.0
    word = token.strip()
    if word in TEMPORAL_CONTINUITY:
        return TEMPORAL_CONTINUITY[word]
    if word in PARTICLES:
        return PARTICLES[word]
    word = word.lower()
    if word == 'al':
        return -0.156 if previous.strip() == 'et' else 0.012
    if word in POSSESSIVES:
        return POSSESSIVES[word]
    if word in PREPOSITIONS:
        return PREPOSITIONS[word]
    if word in CONNECTIVES:
        return CONNECTIVES[word]
    if word in ('both', 'either', 'neither'):
        return 0.052
    if word in ('some', 'several', 'enough'):
        return 0.035
    if word in ('no', 'none', 'zero'):
        return -0.035
    if word in ('other', 'others', 'these', 'those'):
        return -0.028
    if word == 'one':
        return -0.024
    if word in ('does', 'did', 'been'):
        return 0.038
    if word in ('using', 'used', 'uses', 'use'):
        return 0.038
    if word in ('need', 'needs', 'might'):
        return 0.038
    if word in ('who', 'whom', 'whose'):
        return -0.031
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    return (document, token), float(value_for(token, previous))

"""Approximate the positive lexical peaks of a mobile-computing detector.

The largest response is to 'mobile', then Android/iOS and phone vocabulary.
Web, touch, portability, software names and physical-setting words respond
more weakly. We include recognizable split pieces of these words too.
Weights approximate training averages, with casing and spacing adjustments.
A phone/device/app after a mobile-platform modifier gets a phrase boost;
the plural -s after 'mobile' retains some response, as does 'page' after 'web'.
Other tokens get zero: weak, idiosyncratic and negative activity is omitted.
"""
READS = ()

WEB_SERVICES = {
    'twitter', 'facebook', 'instagram', 'pinterest', 'whatsapp', 'atsapp',
    'snapchat', 'telegram', 'yahoo', '微信', '抖音', '微博',
}
PORTABLE_DEVICES = {
    'smartphone', 'smartphones', 'iphone', 'iphones', 'ipad', 'lumia',
    'handheld', 'handset', 'xperia',
}
INTERFACES = {'screen', 'screens', 'tablet', 'tablets', 'bluetooth', 'creen'}
PLATFORM_WORDS = {'native', 'embedded', 'androidx'}
MOBILE_BRANDS = {'nokia', 'samsung', 'vodafone'}
MOBILE_MODIFIERS = {'android', 'ios', 'iphone', 'ipad'}


def lexical_value(spelling, spaced):
    word = spelling.lower()
    if word in {'mobile', 'mobiles'}:
        return 7.9 if spelling[0].isupper() else 7.3
    if word == 'android':
        return 4.0 if spaced else 3.4
    if spelling == 'iOS':
        return 3.5
    if word == 'ios':
        return 1.5 if spaced else 0.3
    if word == 'desktop':
        return 2.8
    if word in PORTABLE_DEVICES:
        return 2.3
    if word == 'phones':
        return 2.05 if spaced else 0.95
    if word == 'phone':
        return 1.25 if spaced else 1.05
    if word in {'telephone', 'cellphone', 'cellphones', 'portable', 'touch',
                'touchscreen', 'wireless'}:
        return 1.2
    if word in {'web', 'webkit'}:
        return 1.65
    if word in WEB_SERVICES or word in PLATFORM_WORDS or word in MOBILE_BRANDS:
        return 0.9
    if word in {'chrome', 'firefox', 'safari', 'mac', 'apple'}:
        return 0.85 if spaced or spelling[0].isupper() else 0.35
    if word in INTERFACES or word in {'digital', 'cellular', 'offline', 'ipod'}:
        return 0.75
    if spelling == 'IoT':
        return 0.8
    if word in {'linux', 'browser', 'internet', 'television', 'tele', 'operating'}:
        return 0.5
    if word == 'windows':
        return 0.6 if spelling[0].isupper() else 0.25
    if word == 'urban':
        return 1.35
    if word in {'rural', 'indoor', 'outdoor', 'maritime', 'mobility'}:
        return 0.85
    if word in {'coastal', 'marine', 'stationary'}:
        return 0.55
    if word in {'mob', 'mobil', 'obil'}:
        return 1.3
    # Splits of 'mobile', including uppercase MO + BILE.
    if word == 'obile' or spelling == 'BILE':
        return 5.0
    # Chinese mobile/Android and Chinese/Japanese phone vocabulary.
    if spelling == '移动端':
        return 5.3
    if spelling == '手游':
        return 2.0
    if spelling in {'移动', '安卓'}:
        return 3.8
    if spelling in {'手机', '手機', '手机版', '智能手机', 'スマホ'}:
        return 2.8
    # Russian and Spanish forms of 'mobile'.
    if word in {'мобиль', 'móvil'}:
        return 4.0
    # Telephone, city, action, webpage; then movement/screen/touch/Internet.
    if spelling in {'电话', '電話', '打电话', '城市', '行动', '网页'}:
        return 1.0
    if word == 'телефон':
        return 1.1
    if spelling in {'动', '動', '移', '屏', '触', '互联网'}:
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('./_-(')
    word = spelling.lower()
    value = lexical_value(spelling, bool(token[:1].isspace()))
    if spelling == 'mobile' and token[:1].isalpha() and previous:
        if carry[2].isalpha():
            value = 4.0
    if word == 'phone' and previous in {'i', 'smart'}:
        value = 2.1 if previous == 'i' else 1.6
    if previous in {'mobile', 'mobiles'} | MOBILE_MODIFIERS:
        mobile = previous in {'mobile', 'mobiles'}
        if word in {'phone', 'phones'}:
            value += 1.4 if mobile else 1.0
        elif word in {'device', 'devices'}:
            value = (1.7 if word == 'device' else 2.2) if mobile else 1.7
        elif word in {'app', 'apps', 'application', 'applications', 'アプリ'}:
            value = 0.85
        elif word in {'technology', 'network', 'version', 'terminal', 'number'}:
            value = 0.6
        elif token == 's' and mobile:
            value = 4.1
    elif word in {'device', 'devices'}:
        value = 0.15
    if previous == 'web' and word in {'page', 'pages'}:
        value = 0.55
    return (document, word, token[-1:]), float(value)

programs.haiku:
"""Clause-openers: the component goes negative on the word that opens a dependent clause
(whether, if, because, although, unless...), and on 'that' when it opens a clause after a
verb of saying, believing or showing."""
READS = ()

WHETHER = {"whether": -9.0, "是否": -4.0}
CONJ = {"if": -1.2, "because": -1.0, "although": -1.1, "though": -1.5, "unless": -2.0,
        "either": -1.2, "whatever": -1.7, "regardless": -1.7, "whenever": -0.8,
        "weather": -1.5, "wenn": -0.9, "dass": -0.8, "如果": -0.5}
CLAUSE_VERBS = set("""say says said saying show shows showed shown showing find finds found know knows
knew known think thinks thought believe believes believed suggest suggests suggested suggesting
indicate indicates indicated indicating conclude concluded mean means meant reveal reveals revealed
note notes noted notice noticed ensure ensures ensured ensuring assure assures assured assume assumes
assumed assuming state states stated claim claims claimed insist insisted argue argued hope hoped
hoping sure confirm confirmed prove proved demonstrate demonstrated realize realized understand
understood feel felt expect expected report reported agree warn promise suppose supposed""".split())
WEAK_THAT = {"so", "such", "is", "fact", "and"}
NO_CLAUSE = {",", ".", "but", "to", "of", "in", "on", "for", "from", "with", "than", "do", "at", "by", "the", "a"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    word = tok.lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in WHETHER:
        value = WHETHER[word]
        if tok == "Whether":
            value = -10.0
    elif word in CONJ:
        value = CONJ[word]
    elif word == "that":
        if prev in CLAUSE_VERBS:
            value = -1.2
        elif prev in WEAK_THAT:
            value = -0.5
        else:
            value = -0.15
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A short vowel-pair spelling detector, chiefly AU and AI.

Negative spikes are largest on short fragments such as aud, aut, ait and
air. Length, adjacent consonants, word spacing and capitalization adjust
their size. Related letter pairs are weaker; most tokens stay near zero.
The previous token supplies vowel pairs split at a token boundary.
"""
READS = ()
PAIRS = ('au', 'ai', 'ei', 'oi', 'ao', 'ae', 'eu', 'ui')
OTHER = {'ei': -0.3, 'oi': -0.25, 'ao': -0.4,
         'ae': -0.4, 'eu': -0.35, 'ui': -0.28}


def spelling_score(token):
    text = token.strip().lower().replace('ä', 'a')
    for pair, value in (('αι', -0.8), ('ау', -0.9), ('ائ', -0.9)):
        if pair in text:
            return value
    for pair in PAIRS:
        k = text.find(pair)
        if k < 0:
            continue
        left, tail = text[:k], text[k+2:]
        prev, nxt = left[-1:], tail[:1]
        vowels = sum(c in 'aeiou' for c in left)
        spaced = token[:1].isspace()
        n = len(tail)
        if pair == 'au':
            if n == 0:
                return -0.27 if vowels else (-0.65 if spaced else -1.25)
            if vowels > (1 if n == 1 else 0):
                return -0.04
            if n == 1:
                if nxt == 'x':
                    return -0.6
                if spaced:
                    if k > 1 and not token.strip()[:1].isupper():
                        return -0.3
                    return -1.2 if nxt in 'fg' else -1.95
                value = -3.2 if k == 0 else -1.8
                return value * (0.75 if token.strip()[:1].isupper()
                                or nxt in 'fg' else 1.0)
            if n == 2:
                return -1.8 if k == 0 and not spaced else -0.9
            if tail[1:2] == 'h' or prev == 'l':
                return -0.2
            return -1.0 if nxt == 'd' else (-0.3 if n >= 7 else -0.6)
        if pair == 'ai':
            value = -0.5 if not tail else (-1.2 if nxt in 'trdsm' else -0.55)
            if n >= 3:
                value *= 0.55
            if k > 1:
                value *= 0.08
            elif k == 1:
                factor = 0.25
                if (prev == 'w' and nxt == 't') or (prev == 'p' and nxt == 'n'):
                    factor = 1.0
                elif prev in 'hf' and nxt == 'r':
                    factor = 0.55
                elif prev == 'r' and nxt == 'd':
                    factor = 1.25
                value *= factor
            return value
        if pair == 'ei' and k == 0 and tail.startswith(('g', 'ng')):
            return -0.9
        return OTHER[pair] * (0.2 if vowels or k > 1 or n > 2 else 1.0)
    return -0.001


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    boundary = prev[-1:].lower() + token[:1].lower()
    value = spelling_score(token)
    if boundary in ('au', 'ау', 'äu'):
        value = -1.0 if len(token) <= 3 else -0.6
        if boundary == 'äu':
            value *= 0.5
    elif boundary in ('ai', 'аи'):
        value = -0.55 if len(token) <= 3 else -0.4
    elif boundary == 'ao':
        value = -0.45
    elif (token.lower().startswith('ai')
          and prev[-1:] in tuple('BCDFGHJKLMNPQRSTVWXYZ')):
        value *= 1.7
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP unit 5212 (down_proj component 5212).

What it does: it responds to a verbal negation ("not", "n't", "never",
"cannot", Chinese 不 / 未, Russian не, German nicht) and to the word that
comes right after it. The response is strongest when the word after the
negation is one that naturally follows "not" or "don't" ("sure", "know",
"yet", "even", "enough", "quite"), moderate for ordinary verbs, adjectives
and nouns ("not have", "not be"), and near zero when the next token is
punctuation, an article, "only" or "just". Determiner "no" and words like
"without" or "non-" barely fire. Outside negation it weakly fires on "only",
"!=" (not-equal) and "to be".

How to read the numbers: the values are rough mean activations, not fitted
coefficients: 3 = strong, 1 = ordinary, 0.5 = weak, 0 = none."""

READS = ()

# How strongly the negator before the current token opens the response.
NEGATOR_STRENGTH = {
    "not": 1.0, "'t": 1.1, "’t": 1.1, "never": 0.5, "cannot": 0.6,
    "不": 2.6, "未": 1.0, "не": 0.6, "nicht": 0.4, "không": 1.0,
    "without": 0.3, "non": 0.3, "no": 0.0, "没": 0.2, "dont": 0.7,
}
# Words that naturally follow "not" / "don't": a strong response.
AFTER_NEGATION_STRONG = {
    "sure", "know", "yet", "even", "enough", "quite", "exactly", "necessarily",
    "understand", "really", "very", "much", "always", "clear", "remember",
}
# Words that barely respond after a negation.
AFTER_NEGATION_NONE = {"only", "just", "the", "a", "an", ".", ",", "\n", "", "?", "。", "，"}


def clean(token):
    return token.strip().lower()


def negator_strength(prev):
    if prev in NEGATOR_STRENGTH:
        return NEGATOR_STRENGTH[prev]
    if prev.endswith("不"):
        return 2.6
    if prev.endswith("未"):
        return 1.0
    return None


def step(carry, prefix, upstream):
    cur = clean(prefix.token_strings[-1])
    same_doc = prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = clean(prefix.token_strings[-2]) if same_doc else ""
    strength = negator_strength(prev) if same_doc else None
    if strength is not None:
        if cur in AFTER_NEGATION_STRONG:
            return None, 2.5 * strength
        if cur in AFTER_NEGATION_NONE:
            return None, 0.1 * strength
        return None, 1.0 * strength
    if cur in ("only", "!="):
        return None, 0.7
    if cur == "be" and prev == "to":
        return None, 0.45
    return None, 0.0

programs.sol:
"""Approximate the continuation of a just-closed expression or quotation.

Equality, arrows and conjunctions get positive values; another word or number
usually gets a negative value. Quotes make a weaker contrast than brackets.
Whitespace, fused symbols and document starts receive small adjustments.
This is a boundary heuristic, not a bracket parser. Context resets between
documents; ordinary token-specific background variation is left at zero.
"""
import unicodedata

READS = ()
BRACKETS = {')': 1., ']': .88, '}': .73, '）': .65,
            '】': .5, '》': .5, '」': .5, '』': .5}
QUOTES = '\"\'`”’'

# Grammatical categories of words that can follow a parenthesized phrase.
LINKS = {}
for words, value in (
    ('and or', .57), ('is', .46), ('are be const', .23),
    ('was were has can will would should must could to as into', .12),
    ('have may but', -.04), ('for by if return', -.12),
    ('in on at from with that which', -.31), ('the of', -.65),
    ('a', -.49), ('I this', -.92), ('The', -.35),
    ('else', .73), ('catch', .35),
):
    LINKS.update(dict.fromkeys(words.split(), value))

OPS = {'=': 1.6, '==': 1.15, '===': 1.05, '!=': .98, '!==': .9,
       '=>': 1.28, '->': 1.37, '<-': .85, '→': 1.1, '⇒': 1.1,
       '+': .92, '-': .66, '*': .63, '/': .63, '**': .5,
       '>': .76, '<': .5, '>=': .8, '<=': .82, '&&': .87, '||': .6,
       '|': .3, '&': .5, ':=': 1.4, ':': .81, '?': .47, '^': .4,
       '+=': 1.05, '-=': .8, '<<': .45, '>>': .45,
       '–': .53, '—': .49, '−': .5, '≤': .85, '≥': .9, '≈': .55}
OP_ORDER = tuple(sorted(OPS, key=len, reverse=True))
QUOTE_OPS = {'+': .24, '-': .28, '*': .13, '/': .28, '|': .21,
             '&&': .44, '||': .35, ':': .41}


def continuation(token, quoted=False):
    s = token.strip()
    spaced = token.startswith(' ')
    if not s:
        if token == ' ':
            return -.02 if quoted else -.48
        return .15 if quoted and '\n' in token else 0.
    if s.startswith('<|'):
        return 0.
    op = next((o for o in OP_ORDER if s.startswith(o)), None)
    if op:
        if quoted:
            if '=' in op or op in ('->', '→', '⇒'):
                v = .7
            else:
                v = QUOTE_OPS.get(op, .4 * OPS[op])
            v *= 1. if spaced else .6
        else:
            v = OPS[op] * (1. if spaced else .85)
            if op == '-' and not spaced:
                v *= .25
        return v * (.65 if s != op or '\n' in token else 1.)
    if spaced and s in LINKS:
        if quoted:
            return {'and': .4, 'or': .4, 'is': .32,
                    'are': .21, 'to': .16}.get(s, .06)
        return LINKS[s]
    if s[0] in ')]}）】》」』':
        v = .35 if quoted else (1.34 if spaced and s[0] == ')' else .9)
        return v * (.6 if '\n' in token else 1.)
    if s[0] in '([{（《「':
        if quoted:
            return .03
        return {'(': -.25, '[': -.07, '{': .2}.get(s[0], -.15)
    if s[0] in QUOTES + '“‘':
        if spaced and s in ('"', "'", '“', '‘'):
            return -.06
        return (-.07 if s == '``' else .1) if quoted else .55
    if s[0] == '\\':
        return .03 if s == '\\' and not spaced else (.1 if quoted else .4)
    if s[0] in '$_^':
        return .07 if quoted else .25
    category = unicodedata.category(s[0])
    if category[0] in 'PS' or category == 'No':
        return .25 if quoted else .45
    if s in ('和', '与', '及', '或', '是'):
        return .4
    if quoted:
        return -.1 if spaced else -.02
    if any('\u3040' <= c <= '\u9fff' for c in s):
        return -.3
    if not spaced:
        return -.9
    return -.6 if s[0].isupper() else -.45


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    same = carry is not None and carry[0] == doc
    previous, older = carry[1:] if same else ('', '')
    closer, strength = previous[-1:], 1.
    if previous == ' ' and older in BRACKETS:
        closer, strength = older, (.6 if token.isdigit() else .12)
    elif previous and previous[-1].isspace():
        closer, strength = previous.rstrip()[-1:], .08
    value = 0.
    if closer in BRACKETS:
        value = strength * BRACKETS[closer] * continuation(token)
        if token.strip() == 'else' and strength == 1.:
            value = .73
    elif closer and closer in QUOTES:
        value = strength * continuation(token, quoted=True)
    else:
        s = token.strip()
        if len(s) > 1 and s[0] in ')]}' and s[1] in '=+':
            value = .72 if s[1] == '=' else .28
    if not same:
        s = token.strip().lstrip('"\'')
        if s and s[0] in ')]}':
            value = {')': 2., ']': 1.3, '}': 1.}[s[0]]
            value *= 1. if all(c in ')]}' for c in s) else .6
    return (doc, token, previous[-1:]), float(value)

programs.luna:
"""Predict relational operators and ordinary words after a closed phrase.

Operators after a parenthesis, bracket, brace, or quote tend to activate this
component positively.  Plain words after parentheses and brackets lean
negative; explicit conjunctions and function words are handled separately.
"""

READS = ()

_EQUALITY = {"=", "==", "===", "!=", "<=", ">=", "=>", "->", "→", "⇒"}
_ARITHMETIC = {"+", "-", "*", "/", "^", "&&", "||"}
_CONNECTORS = {"and", "or", "is", "else"}
_FUNCTION_WORDS = {"of", "the", "in", "a", "at", "on", "from", "with", "that"}
_EXPRESSION_ENDS = (")", "]", "}", "\"", "'", "”", "’")
_GROUP_ENDS = (")", "]", "}")


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    current = prefix.token_strings[-1].strip()
    previous = prefix.token_strings[-2].rstrip()
    follows_close = previous.endswith(_EXPRESSION_ENDS)
    follows_round_or_square = previous.endswith((")", "]"))

    if follows_close and current in _EQUALITY:
        return None, 1.25
    if follows_close and current in _ARITHMETIC:
        return None, 0.65
    if follows_close and current in _CONNECTORS:
        return None, 0.45
    if follows_close and current in _FUNCTION_WORDS:
        return None, -0.5

    # Joined tokens such as `)=` or `]=` still visibly close an expression.
    if current.endswith((")=", "]=", "}=")):
        return None, 0.75
    if follows_close and current.startswith(_GROUP_ENDS):
        if current.startswith(")"):
            return None, 1.1
        return None, 0.6

    if follows_round_or_square and current.isalpha():
        return None, -0.2
    return None, 0.0

programs.sol:
"""Predict the negative response to opening quotations.

Quotes attached to an opening list/object delimiter are strongest. A separate
opening quote is stronger after articles, prepositions and naming words than
after punctuation or code separators. Only the immediately preceding token is
remembered, within the same document. Ordinary text is assigned zero.
"""
READS = ()

# Familiar word classes, paired with strengths for a following quotation.
WORD_CLASSES = (
    (-1.12, 'a an the'),
    (-0.97, 'this that these those my your his her its our their any each every '
     'some another such'),
    (-0.94, 'of to in on for at by with from into as about through over under '
     'between after before without within upon like'),
    (-0.80, 'is are was were be been being am'),
    (-1.01, 'say says said call calls called name named term terms phrase '
     'phrases word words title titled entitled mean means defined known'),
    (-0.61, 'and or but nor yet so'),
    (-0.18, 'return case echo print printf include import require typeof '
     'comment default else then throw yield'),
)
WORD_CLASSES = tuple((value, set(words.split())) for value, words in WORD_CLASSES)


def quotation_context(previous):
    p = previous.strip()
    if not previous:
        return -0.21
    if not p:
        return 0.11
    if p in ("'s", '’s', '-called'):
        return -0.94
    if any(c in p for c in '\"\'”’'):
        return 0.02
    for value, words in WORD_CLASSES:
        if p.lower() in words:
            return value
    if p.isalpha():
        if any('\u3400' <= c <= '\u9fff' for c in p):
            return -0.40
        return -0.75 if previous[0].isspace() or not p.isascii() else -0.52
    if p.isdigit():
        return -0.35
    if p[-1] in '.。!?':
        return -0.15
    if p[-1] in ',，:：':
        return -0.23
    if p in ('=', ':=', '+=', '-=', '=>', '+', '<<', '>>'):
        return 0.02
    return -0.24


def step(carry, prefix, upstream):
    token, document = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    value, text = 0.0, token.lstrip()
    if token in (' \"', " '", ' “', ' ‘'):
        value = quotation_context(previous)
        if token == " '":
            value += 0.18 if value < -0.30 else 0.06
        elif token in (' “', ' ‘') and -0.79 < value < -0.19:
            value -= 0.10
    elif text and text[-1] in '\"\'“‘':
        body = text[:-1]
        if body and not any(c.isalnum() for c in body):
            if '{' in body or '[' in body:
                value = -1.12
                if body == '{':
                    value = -1.05 if token[0].isspace() else -1.27
                elif ']' in body or ':' in body:
                    value = -0.87
            elif '(' in body:
                value = -0.55 if token[0].isspace() else -0.11
                if '=' in body or '!' in body:
                    value = -0.90
            elif body == '=':
                value = -0.084
        elif not body:
            if text in ('“', '‘'):
                value = -0.50 if previous.strip().isalpha() else 0.0
            else:
                value = -0.084 if text == '\"' else -0.048
    elif text == '「':
        value = -0.53 if previous.strip().isalpha() else -0.08
    elif token in (' «', ' „'):
        value = -0.37
    elif token == ' `':
        context = quotation_context(previous)
        value = 0.25 * context if context < -0.40 else 0.10
    elif token == '`':
        value = 0.072
    return (document, token), float(value)

