programs.sol:
"""An indefinite-noun-phrase signal, dominated by English 'a' and 'an'.

Articles are strongest after possession/provision verbs, weaker after location
prepositions, and much weaker as letters or mathematical variables. Capitalized
articles and other determiners have smaller responses, as do several non-English
noun-phrase introducers. A short history of function words distinguishes English
articles from the same spellings in other languages.
The history resets at document boundaries; no future text is consulted.
"""
READS = ()

POSSESSION = {'have', 'has', 'had', 'having'}
ACQUISITION = set('''get find give put receive obtain provide offer require need
    suffer maintain gain buy purchase acquire own possess lack'''.split())
CREATION = set('''create build develop add write produce generate construct
    establish design compose'''.split())
CONTENT = set('use contain include show form hold present'.split())
IRREGULAR = {
    'got': 'get', 'found': 'find', 'gave': 'give', 'made': 'make',
    'built': 'build', 'wrote': 'write', 'written': 'write',
    'took': 'take', 'taken': 'take', 'held': 'hold',
}
VERBS = ACQUISITION | CREATION | CONTENT | {'make', 'take'}
SPATIAL = set('''in on at of from over about during between inside until onto
    around under near'''.split())
LINKERS = set('as to and or that than but up become becomes became becoming'.split())
CONDITIONAL = {'if', 'when', 'where', 'which', 'since', 'because'}
COPULA = {'is', 'are', 'was', 'were', 'be', 'been', 'being', "'s", '’s'}
FOREIGN = set('''que para com uma pelo pela del los las el una der die das und
    nicht ein eine einen pour avec dans une des les de du le la en es por se um
    zu mit auch sich den dem bis ich von dass pero lo más como não
    mais em ou'''.split())
ENGLISH = set('''the and of to is was with have has this that for are from which
    you it can will would been be on in'''.split())


def verb_root(word):
    """Recognize ordinary inflections, but only of the small verb classes above."""
    if word in IRREGULAR:
        return IRREGULAR[word]
    if word in VERBS:
        return word
    for ending in ('s', 'es', 'ed', 'ing'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            undoubled = stem[:-1] if stem[-2:-1] == stem[-1:] else ''
            candidates = (stem, stem + 'e', undoubled)
            for candidate in candidates:
                if candidate in VERBS:
                    return candidate
    return word


def article_after(previous, before):
    word = previous.strip().lower()
    root = verb_root(word)
    if word in POSSESSION:
        return 4.95
    if root in ACQUISITION or word == 'there':
        return 4.8
    if root in {'make', 'take'}:
        return 4.5
    if root in CREATION:
        return 4.25
    if root in CONTENT or word == 'given':
        return 3.8
    if word in SPATIAL:
        return 2.45
    if word in LINKERS:
        return 2.85
    if word in CONDITIONAL:
        return 2.35
    if word in COPULA:
        if before.strip().lower() == 'there':
            return 4.7
        if word in {"'s", '’s'}:
            return 3.1
        if before.strip().isdigit() or before.rstrip().endswith((')', '$', '`')):
            return 2.95
        return 3.35
    if word == 'with':
        return 4.15
    if word == 'without':
        return 5.1
    if word in {'such', 'like'}:
        return 3.85
    if word == 'am':
        return 1.8
    if word == 'the':
        return 1.0
    if word in FOREIGN:
        return 0.0
    if word in {'=', '+', '-', '*', '/', '^', '→'}:
        return 0.65
    if word and all(not c.isalnum() for c in word):
        return 1.75
    if len(word) == 1 or word.isdigit():
        return 0.8
    if not word:
        return 1.5
    if not previous[0].isspace():
        return 2.0
    return 3.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, languages = '', '', ()
    else:
        _, previous, before, languages = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    foreign_context = sum(languages) >= 1
    value = 0.0
    if lower in {'a', 'an'} and not foreign_context:
        boundary = token.startswith(' ') or not previous or not previous[-1].isalnum()
        if word == 'AN':
            value = 0.1
        elif word[0].isupper():
            value = (0.9 if lower == 'a' else 1.45) if boundary else 0.25
            sentence_start = ('\n' in previous or
                              previous.rstrip().endswith(('.', '!', '?')))
            if boundary and sentence_start:
                value += 0.5
        elif token.startswith(' '):
            value = article_after(previous, before)
        elif '\n' in previous:
            value = 1.55
        elif previous.rstrip().endswith(('(', '"', '“')):
            value = 1.0
        else:
            value = 0.2 if lower == 'a' else 0.0
    elif lower in {'this', 'these', 'those'}:
        value = 0.72 if word[0].isupper() else 0.88
        if lower == 'this' and word == 'this':
            value = 0.72 if token.startswith(' ') else 0.43
    elif lower == 'each':
        value = 1.0 if token == ' each' else 0.88
    elif lower == 'another':
        value = 1.3 if token == ' another' else 0.95
    elif token in {' no', ' some'}:
        prev = previous.strip().lower()
        if foreign_context:
            value = -0.1
        elif token == ' no':
            value = 1.1 if prev in POSSESSION | COPULA else 0.25
        else:
            value = 0.45 if prev in POSSESSION | COPULA else -0.1
    elif lower in {'any', 'some'}:
        value = -0.07 if word == 'any' else -0.3
    elif lower == 'few':
        value = -0.19
    elif lower in {'ein', 'eine', 'einen', 'einer', 'einem'}:
        # German indefinite articles, including case/gender endings.
        value = {'ein': 0.58, 'eine': 0.83, 'einen': 0.73,
                 'einer': 0.4, 'einem': 0.38}[lower]
        if word[0].isupper():
            value *= 0.7
    elif lower in {'una', 'uma', 'een'}:
        value = 0.7 if lower == 'een' else 0.45
    elif token.endswith('一个'):
        value = 1.15
    elif token == 'この':
        value = 0.53
    elif token in {'_a', '-a', '-an'}:
        value = 0.9
    elif token in {'(a', '(A'}:
        value = 0.17

    # Count function-word evidence over 24 tokens. Undo a marker if its token
    # turns out to have been just the beginning of a longer word.
    extends_word = (previous and token and previous[-1].isalpha()
                    and token[0].isalpha())
    if extends_word and languages:
        languages = languages[:-1] + (0,)
    boundary = token and (token[0].isspace() or not previous
                          or not previous[-1].isalpha())
    marker = int(lower in FOREIGN) - int(lower in ENGLISH)
    languages = (languages + (marker if boundary else 0,))[-24:]
    return (doc, token, previous, languages), float(value)

