programs.sol:
"""Approximate a typographic-number and mathematical-notation detector.

Raised/lowered digits and digits in non-Latin scripts get large positive
values; fullwidth digits and other notation get smaller ones. Values
are empirical averages for these readable glyph and syntax classes;
ordinary vocabulary is deliberately left near zero.
A short suffix recognizes caret exponents and fraction-like slashes.
Three named IDs handle incomplete UTF-8 prefixes that cannot decode alone.
"""
import re
import unicodedata as ud

READS = ()
SUBSCRIPT_PREFIX = 15896           # E2 82: U+2080..U+20BF
SUPERSCRIPT_PREFIX = 52133         # E2 81: U+2040..U+207F
SPACED_SUPERSCRIPT_PREFIX = 77137  # space + E2 81


def glyph_value(s):
    if len(s) != 1:
        return None
    name = ud.name(s, '')
    if s in '¹²³':
        return {'¹': 1.43, '²': 2.20, '³': 2.08}[s]
    if name.startswith('SUPERSCRIPT') and s.isdigit():
        return 1.83 if s == '⁰' else 2.38
    if 'SUBSCRIPT' in name:
        if not s.isdigit():
            return 0.70
        return 1.53 if s == '₀' else (1.67 if s in '₁₂' else 2.12)
    if s.isdecimal() and not s.isascii():
        if name.startswith('FULLWIDTH'):
            return 1.0 if s == '０' else 0.85
        if name.startswith('EXTENDED ARABIC-INDIC'):
            return 2.15
        if name.startswith('ARABIC-INDIC'):
            return 2.9
        return 1.9 if name.startswith('THAI') else 2.5
    if name.startswith('CIRCLED DIGIT'):
        return 0.63 + 0.11 * ud.digit(s)
    if name.startswith('VULGAR FRACTION'):
        return 0.32
    if s in '⁻⁺ⁿ':
        return {'⁻': 1.1, '⁺': 0.8, 'ⁿ': 1.0}[s]
    if 'MATHEMATICAL' in name:
        return 0.30
    if 'FULLWIDTH LATIN' in name:
        return 0.52 if s.isupper() else 0.35
    if s == '✝':
        return 0.27
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    # Only split characters require decoding the joined token prefix.
    char = prefix.text_prefixes[-1][-1:] if '�' in s else s
    value = glyph_value(char)
    token = prefix.token_ids[-1]
    if token == SUBSCRIPT_PREFIX:
        value = 1.34
    elif token == SUPERSCRIPT_PREFIX:
        value = 0.98
    elif token == SPACED_SUPERSCRIPT_PREFIX:
        value = 0.35
    if value is None:
        value = 0.002
        if s == '°':
            value = 0.36 if re.search(r'angle|sin|cos|tan|°', old) else 0.20
        elif s.strip() in ('°C', '°F'):
            value = 0.11
        elif s.strip().lower() in ('squared', 'quared'):
            value = 0.66 if s.strip().lower() == 'squared' else 0.33
        elif s in (' ⇒', ' ≠'):
            value = 0.25
        elif s == '⇒':
            value = 0.07
        elif s.strip() in '×÷±√≠≤≥·' and len(s.strip()) == 1:
            value = 0.16
        elif s.isascii() and len(s) == 1 and s.isdigit():
            if re.search(r'\^\{?$', old):
                value = max(0.0, 0.35 - 0.046 * int(s)) if int(s) > 1 else 0.01
                if old.endswith('{'):
                    value *= 0.7
        elif '/' in s and len(s) <= 3 and '//' not in s and '\n' not in s:
            before = (old + s[:s.index('/')]).rstrip()
            word = re.search(r'[^\W\d_]+$', before)
            variable = word is not None and len(word[0]) == 1
            math = before[-1:].isdigit() or before.endswith(')') or variable
            path = '://' in old or re.search(r'\d+/\d+$', before)
            value = 0.25 if math and not path else 0.02
            if '(' in s:
                value *= 0.6
        elif s == '^':
            value = 0.12 if re.search(r'[a-zA-Z]$', old) else 0.02
    return (doc, (old + s)[-48:]), float(value)

