def step(carry, prefix, upstream):
    """Give script digits a strong positive value and related numeric glyphs a smaller one."""
    value = 0.0
    for char in prefix.token_strings[-1]:
        name = unicodedata.name(char, "")
        if "SUPERSCRIPT" in name:
            value = max(value, 2.1)
        elif "SUBSCRIPT" in name:
            value = max(value, 1.6)
        elif char in "０１２３４５６７８９":
            value = max(value, 0.9)
