    return None, float(value)

programs.sol:
"""Approximate discourse pointers and a few phrase completions.

The strongest negative response is 'the following', with weaker responses to
'as follows', 'here is/are', 'in particular', and multilingual pointing words.
Other rules recognize phrasal uses of 'come', 'end up with', and 'begin with'.
'Come in' and 'above' without 'the' get small positive responses.
All other tokens get zero: the diffuse token-specific background is omitted.
Only the last two token pieces are retained, reset at document boundaries.
"""
READS = ()
COME = {'come', 'came', 'comes', 'coming'}
END = {'end', 'ended', 'ends', 'ending'}
BEGIN = {'begin', 'began', 'begins', 'beginning'}
START = {'start', 'started', 'starts', 'starting'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    prev = previous.lower()
    value = 0.0

    if word == 'following':
        value = -0.20
        if prev == 'the':
            value = -1.27 if previous == 'the' else -1.18
        if raw == 'Following':
            value = -0.80 if prev == 'the' else -0.09
    elif word == 'follows':
        value = -0.76 if prev == 'as' else -0.13
    elif word == 'particular':
        value = -0.37 if prev == 'in' else -0.10
    elif word in {'is', 'are', "'s", '’s'}:
        if prev == 'here':
            value = -0.28 if previous[:1].isupper() else -0.14
        elif prev in {'following', 'below'}:
            value = -0.30
    elif word == 'above':
        value = -0.16 if prev == 'the' else 0.14
    elif word == 'below' and prev in {'the', 'shown', 'listed', 'given'}:
        value = -0.45 if prev == 'the' else -0.29

    # Other-language equivalents of 'following' / 'here are'.
    if word in {'以下', '以下是', '如下'}:
        value = -0.40
    elif word in {
        'siguiente', 'siguientes', 'seguint', 'seguinte', 'seguintes'
    }:
        value = -0.45 if word == 'siguiente' else -0.60
    elif word == 'ующ' and prev == 'след':  # Russian следующий
        value = -0.90
    elif (word in {'gende', 'genden', 'gender', 'gendes'}
          and prev in {'fol', 'vol'}):
        value = -0.68  # German folgende, Dutch volgende
    elif word in {'ant', 'ante', 'ants', 'antes'} and prev == 'suiv':
        value = -0.47  # French suivant(e)(s)
    elif word == 'ici' and prev == 'vo':  # French voici
        value = -0.46
    elif word == '記' and prev == '下':  # Japanese 下記
        value = -0.54
    elif word == '列' and prev == '下':  # Chinese 下列
        value = -0.74

    # Phrasal-verb completions. The 'up with' peak depends on the verb.
    if word == 'with':
        if prev == 'up':
            value = -0.53 if before.lower() in COME | END else -0.17
        elif prev in BEGIN:
            value = -0.34
        elif prev in START:
            value = -0.18
        elif prev in COME:
            value = -0.27
    elif word == 'across':
        value = -0.54 if prev in COME else -0.08
    elif word == 'in' and prev in COME:
        value = 0.35

    return (doc, raw, previous), value

