"""A lexical beauty/America detector, centered on the character 美.

美 means beauty and abbreviates America in Chinese/Japanese. A separate 美
has the strongest negative response; compounds and translations are weaker.
Food/perfection compounds are weaker still. Case and word boundaries adjust
English responses. Completed byte-split 美 is recognized from decoded text.
Country abbreviations also respond; 日 is weaker after a digit. Other tokens
receive zero, omitting small unrelated lexical effects.
"""
READS = ()

BEAUTY_DESCRIPTIONS = {
    'aesthetic': -1.5, 'aesthetics': -1.5, 'gorgeous': -1.5,
    'picturesque': -1.9, 'breathtaking': -1.0, 'elegant': -0.9,
    'stunning': -0.9, 'admire': -0.8, 'beau': -0.9,
    'attractive': -0.6, 'artistic': -0.6, 'delicious': -0.65,
    'lovely': -0.6, 'красив': -1.85, 'красот': -2.1,
    'schö': -0.85, 'schön': -0.8, 'schöne': -0.75,
    'đẹp': -2.0, 'güzel': -0.8, '漂亮': -1.6, '漂亮的': -1.6,
    '颜值': -1.25, '女神': -1.4,
}
COUNTRY_NAMES = {
    'американ': -3.7, 'США': -1.6, 'Mỹ': -3.6, 'améric': -2.0,
    '미국': -2.4, 'アメリカ': -2.4, 'USA': -0.56,
    '英': -2.1, '俄': -1.3,
}


def beauty_character(word, before):
    if word == '美':
        if before in {'欧', '歐', '完', '優', '优'}:
            return -6.7
        if before in {'南', '北', '赞', '讚', '贊', '耽'}:
            return -7.3
        return -9.85 if before and not before.isalnum() else -9.3
    if word in {'美的', '之美', '中美'}:
        return -5.8
    if word in {'美感', '优美', '優美'}:
        return -4.6
    if word == '美國':
        return -4.0
    if word in {'美国', '美丽', '美麗', '美女', '美人', '美しい',
                '精美', '最美', '美军', '美术', '美方', '美洲', '北美', '审美'}:
        return -3.4
    if word.startswith('完美'):
        return -1.4
    if ('美元' in word and word != '美元') or word in {'美食', '美味', '甜美'}:
        return -1.2
