        value = -9.75
    elif '美' in word:
        before = prefix.text_prefixes[-2][-1:] if same_doc and word == '美' else ''
        value = beauty_character(word, before)
    elif word == '미':
        value = -4.2 if spaced else -3.5
    elif lower.lstrip('-') in {'american', 'americans'}:
        value = -2.6 if lower.endswith('american') else -2.0
        value *= 1.0 if spaced else 0.9
    elif lower in {'america', 'americas', 'américa', 'amer'}:
        value = -1.45 if lower == 'america' else -0.9
        if lower == 'amer':
            value = -1.6 if spaced else -0.5
    elif word == 'US':
        attached = previous[-1:].isalpha()
        value = -1.72 if spaced else (-0.5 if attached else -1.4)
    elif lower in {'beauty', 'beautiful', 'beautifully', 'beaut'}:
        value = -3.35 if lower == 'beauty' else -3.0
        if lower == 'beaut':
            value = -1.65
        elif word[:1].isupper():
            value *= 0.8 if lower == 'beauty' else 0.86
        value *= 1.0 if spaced else 0.9
    elif word == '日':
        value = -0.45 if previous[-1:].isdigit() else -0.75
    else:
        value = COUNTRY_NAMES.get(word, BEAUTY_DESCRIPTIONS.get(lower, 0.0))
    return None, value

programs.luna:
"""Approximate sparse activations around liberty, rights, and autonomy words.

The clearest cues are liberty/freedom, rights/privacy, and free/open access.
Broader autonomy words are weaker. These word-level rules miss context cues
and the component's other responses.
"""
READS = ()

LIBERTY = {"liberty", "liberties", "freedom", "freedoms"}
RIGHTS = {"rights", "privacy", "quyền"}
OPEN_ACCESS = {"free", "open", "license", "licenses", "licensed", "开放"}
AUTONOMY = {
    "choice", "justice", "judicial", "control", "boundaries",
    "随便",
    "独立", "自由",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(" /.,;:!?\\\"'()[]{}")
    if word in LIBERTY:
        return None, 5.5 if word.startswith("freedom") else 5.0
    if word.startswith("libert"):
        return None, 2.8
    if word.startswith("freely"):
        return None, 2.2
    if word.startswith("democra"):
        return None, 0.8
    if word.startswith("indiscrimin"):
        return None, 1.3
    if word.startswith("independ") or word.startswith("autonom"):
        return None, 1.5
    if word.startswith("flexib"):
        return None, 1.8
    if word.startswith("arbitr"):
        return None, 1.6
    if word in RIGHTS:
        return None, 2.3
    if word == "free":
        return None, 1.6
    if word in OPEN_ACCESS:
        return None, 1.0
    if word in AUTONOMY:
        return None, 0.6
    return None, 0.0

programs.sol:
"""Approximate a local spelling-continuation signal using letters and suffixes.

Large training activations often follow chunks ending in s/z-like letters.
A/e-like continuations and apostrophes are positive; i/u-like beginnings
are generally negative. Chunks spelled ed/es/ing and able/ably/ability are
positive exceptions; the latter also get a small independent baseline.
Length and final-letter classes adjust the magnitude. X and sh give weaker
cues. An s-like -> e -> a sequence gets a second-chunk positive response.
Leading whitespace and new documents break that sequence. This captures
broad spelling patterns, not token-specific activation strengths.
"""
import unicodedata

READS = ()
S_SOUNDS = set('szсзσςſسز')
WEAKER_S_SOUNDS = set('шщжцสศษ')
VOWELS = set('aeiouyаеёиоуыэюяαεηιουω')
STOPS = set('ptkbdgптбкдгπτβκδγ')


def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def strength(previous, possessive=False):
    if not previous:
        return 0.0
    end = previous[-1]
    if end in S_SOUNDS:
        n = len(previous)
        if possessive and n > 4:
            return 0.85
        if n == 1:
            return 0.77
        return 1.0 if n <= 4 else (0.81 if n <= 6 else 0.68)
    if end == 'x':
        return 0.62
    if end in WEAKER_S_SOUNDS or previous.endswith('sh'):
        return 0.13
    return 0.0


def response(chunk):
    if chunk in {"'", '’'}:
        return 1.1 if chunk == "'" else 1.3
    if not chunk or chunk[0].isspace():
        return 0.0
    n, first, end = len(chunk), chunk[0], chunk[-1]
    if chunk in {'ed', 'es', 'ing'}:
        return 0.81
    if chunk.startswith(('able', 'ably', 'ability')):
        return 1.77
    if first in 'aаαا':
        if n > 4:
            return 0.79
        return 1.05 if end in VOWELS or end in S_SOUNDS else 1.27
    if first in 'eеэε':
        if n > 5:
            return 0.3
        if n > 3:
            return 0.93
        return 1.58 if end in STOPS else 1.23
    if first in 'iyиι':
        return -0.56 if n <= 4 else -0.2
    if first in 'uуυ':
        return -0.66 if n <= 3 and end in 'lrлр' else -0.22
    if first.isdigit():
        return 0.18
    if first in 'hхχ' and n <= 3:
        return -0.34
    if first in S_SOUNDS:
        return -0.22 if n <= 3 else -0.04
    if first in 'pfbmvwпфбмв':
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    chunk = letters(prefix.token_strings[-1])
    previous, older = ('', '') if carry is None or carry[0] != doc else carry[1:]
    cue = strength(previous, chunk in {"'", "’"})
    value = cue * response(chunk)
    if chunk.startswith(('able', 'ably', 'ability')):
        value += 0.3
    if (not cue and chunk.startswith('a') and previous.startswith('e')
            and strength(older)):
        value += 0.6
    return (doc, chunk, previous), float(value)

"""A detector for counted units, strongest for durations.

The current word supplies a unit's strength. A preceding numeral, number
word, article or quantifier raises it; calendar references such as 'this
year' are much weaker. Plural durations are stronger than singular ones.
Other measurements and amount expressions receive smaller responses.
The response continues weakly onto 'of', 'ago' and 'later' after a duration;
document boundaries clear that memory.
"""
import re

READS = ()

# Calibrated strengths: singular baseline/gain, plural baseline/gain.
# Gain multiplies the preceding word's degree of quantification.
TIME = {
    'second': (-0.07, 1.47, 2.28, 2.04),
    'minute': (0.40, 2.81, 1.73, 2.74),
    'hour': (0.65, 2.79, 1.42, 3.10),
    'day': (-0.53, 2.30, 0.75, 2.99),
    'week': (-0.03, 3.18, 2.22, 3.24),
    'month': (-0.17, 3.42, 2.22, 2.96),
    'year': (-0.32, 3.22, 1.46, 2.63),
    'decade': (0.91, 1.87, 1.56, 2.10),
    'century': (-0.10, 2.25, 1.54, 1.78),
}
NUMBER_WORDS = set('zero three four five six seven eight nine ten eleven '
                   'twelve thirteen fourteen fifteen sixteen seventeen '
                   'eighteen nineteen twenty thirty forty fifty sixty '
                   'seventy eighty ninety hundred thousand'.split())
LENGTH = {
    'inch': (1.5, 0.8), 'foot': (0.1, 1.3), 'feet': (1.2, 2.1),
    'yard': (0.6, 1.4), 'mile': (1.0, 1.8),
    'meter': (0.5, 1.6), 'metre': (0.5, 1.6),
    'kilometer': (1.5, 1.5), 'kilometre': (1.5, 1.5),
    'centimeter': (1.2, 1.0), 'centimetre': (1.2, 1.0),
    'millimeter': (1.0, 0.8), 'millimetre': (1.0, 0.8),
    'acre': (1.1, 1.0), 'hectare': (1.2, 1.0),
}
MASS_VOLUME = set('gram kilogram pound ounce ton tonne liter litre gallon '
                  'pint quart milliliter millilitre tablespoon teaspoon'.split())
ABBREVIATIONS = {
    'km': 2.3, 'cm': 1.8, 'mm': 0.9, 'nm': 1.0, 'ft': 1.3,
    'kg': 0.6, 'mg': 0.7, 'ml': 1.1, 'lb': 0.8, 'lbs': 1.6,
    'oz': 0.8, 'ms': 0.9, 'sec': 0.7, 'min': 0.5, 'hrs': 4.0,
    'yr': 1.5, 'yrs': 2.6, 'px': 1.2,
}


def quantity(previous):
    p = previous.strip().lower().lstrip('-')
    if p.isdigit():
        return 1.2
    if p == 'one':
        return 1.5
    if p == 'two':
        return 1.35
    if p in NUMBER_WORDS:
        return 1.6
    if p in {'a', 'an', 'single'}:
        return 1.0
    if p in {'few', 'several'}:
        return 1.35
    if p in {'many', 'multiple', 'half', 'couple'}:
        return 1.05
    if p == 'recent':
        return -0.25
    if p in {'this', 'that', 'these', 'those'}:
        return -0.08
    if p in {'the', 'same', 'previous', 'current',
             'my', 'your', 'his', 'her', 'its', 'their', 'our'}:
        return 0.05
    if p in {'next', 'every'}:
        return 0.65
    if p in {'last', 'first', 'second', 'third', 'past',
             'following', 'coming', 'th', 'st', 'nd', 'rd'}:
        return 0.45
    if p == 'each':
        return 0.6
    if p == 'per':
        return 0.9
    if p in {'square', 'cubic'}:
        return 0.9
    if p == 'of':
        return 0.8
    return 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower().lstrip('_-')
    plural = word.endswith('s')
    stem = word[:-1] if plural else word
    if word == 'inches':
        stem = 'inch'
    if word == 'centuries':
        stem, plural = 'century', True
    q = quantity(previous)
    value = 0.0
    if word == 'of' and carry and carry[0] == doc and carry[3]:
        value = 0.48 * carry[2]
    elif stem in TIME:
        b, g = TIME[stem][2:] if plural else TIME[stem][:2]
        value = b + g * q
    elif stem in LENGTH or word == 'feet':
        b, g = LENGTH.get(word, LENGTH.get(stem))
        value = b + g * q + (0.9 if plural else 0.0)
    elif stem in MASS_VOLUME:
        value = 0.2 + 1.1 * q + (0.7 if plural else 0.0)
        if not token.startswith((' ', '-')) and not previous.strip().isdigit():
            value = 0.0
    elif raw in {'kB', 'MB', 'GB', 'mM'}:
        value = 0.9 if token.startswith(' ') else 0.3
    elif word in ABBREVIATIONS:
        value = ABBREVIATIONS[word]
        if raw != word:
            value *= 0.1
        elif not token.startswith(' '):
            value *= 0.75 if previous.strip().isdigit() else 0.2
    elif word in {'bit', 'little', 'fraction', 'deal'}:
        value = 0.8 if previous.strip().lower() in {'a', 'little'} else -0.15
    elif word in {'while', 'whilst', 'once', 'twice', 'thrice'}:
        value = 0.6
    elif word in {'percent', 'cent', 'cents'} and token.startswith(' '):
        value = 0.4 + 0.7 * q + (0.8 if plural else 0.0)
    elif word == '%':
        value = 0.23 if raw == token else -0.08
    elif stem in {'thousand', 'million', 'billion', 'hundred'}:
        value = 1.1
    elif word in {'times', 'words', 'pages', 'steps', 'digits', 'letters',
                  'rows', 'games', 'points', 'bytes', 'degrees',
                  'dollars', 'euros', 'generations', 'nights'}:
        value = (0.3 if q < 1.0 else 1.2 * q)
    elif word in {'ago', 'later'}:
        after_duration = carry and carry[0] == doc and carry[3]
        value = 0.95 if after_duration else 0.2
    elif word in {'milliseconds', 'microseconds', 'nanoseconds'}:
        value = 2.5
    elif word in {'fortn', 'fortnight'}:
        value = 1.5 + q
    elif word == 'ight' and previous.strip().lower().endswith('fortn'):
        value = 2.0
    elif word in {'imeter', 'imeters', 'ometer', 'ometers'}:
        value = 1.5 + (0.8 if plural else 0.0)
    elif word == 'time':
        if previous.strip().lower() in {'long', 'some', 'little'}:
            value = 0.7
    if value and (stem in TIME or stem in LENGTH):
        if raw.startswith('_'):
            value *= 0.5
        elif raw[:1].isupper() or not token.startswith((' ', '-')):
            value *= 0.6
    if not value:
        value = international_units(raw)
        if raw in FOREIGN_UNITS and not token.startswith(' '):
            value *= 0.3
    return (doc, token, value, stem in TIME), float(value)


# Familiar time and measurement units in several languages.
FOREIGN_UNITS = {
    'horas': 3.5, 'meses': 3.2, 'minutos': 3.9, 'días': 3.3,
    'jours': 2.9, 'mois': 1.6, 'anos': 1.6, 'años': 1.6,
    'лет': 1.6, 'года': 1.3, 'год': 1.4, 'году': 1.0,
    'дней': 3.2, 'часов': 2.7, 'час': 1.4, 'минут': 2.4,
    'metros': 1.9, 'см': 0.8, 'Jahre': 2.5, 'Wochen': 2.7,
    'Minuten': 4.1, 'ngày': 1.7,
}
EAST_ASIAN_TIME = {
    '分钟': 4.2, '分鐘': 3.4, '小时': 3.3, '小時': 3.4,
    '个月': 3.0, '個月': 3.0, '年': 0.75, '天': 1.1,
    '日': 0.6, '分': 0.65, '秒': 2.7,
}
DURATION = re.compile(
    r'^([零〇一二两兩三四五六七八九十百千万萬几幾多数數半\d]*)'
    r'(分钟|分鐘|小时|小時|个月|個月|年|天|日|分|秒)'
    r'(后|後|前|内|內|以上|以下|以来|以來|多|半)?$'
)
EAST_ASIAN_MEASURE = {
    '公里': 4.0, '千米': 2.3, '米': 0.9, '毫米': 2.3,
    '平方米': 2.2, '公顷': 3.3, '亩': 2.9,
    '万': 0.8, '亿': 1.6, '亿元': 2.8, '万元': 2.0,
}


def international_units(raw):
    if raw in FOREIGN_UNITS:
        return FOREIGN_UNITS[raw]
    if raw in EAST_ASIAN_MEASURE:
        return EAST_ASIAN_MEASURE[raw]
    match = DURATION.fullmatch(raw)
    if match:
        number, unit, suffix = match.groups()
        value = EAST_ASIAN_TIME[unit]
        if number and unit in {'年', '天', '日'}:
            value += 0.3 if number == '一' else 1.5
        return value
    return 0.0

"""A local approximation to the component's backward-reference signal.

Explicit pointers ('above', 'earlier', 'aforementioned') give strong negative
values.  Named discourse objects and citation verbs give weaker negative
values, amplified by definite/demonstrative/possessive context: 'the problem',
'our analysis', 'as described'.  Word families share a baseline and a gain.
Plural number words and 'following' supply smaller contrastive signals.
A few non-English backward pointers are recognized as well.

The rules use only this token and the preceding token, reset at document
boundaries. Capitalized forms are weakened; a few pointers have separate
model-start values. Unrecognized tokens predict zero. This detects local
reference language, not the antecedent or whether the reference is valid.
"""
READS = ()


def words(text):
    return frozenset(text.split())


CITATION = words('mentioned described discussed outlined cited referenced '
                 'listed stated noted shown reported')
STRONG_REFERENCE = words('aforementioned foregoing aforesaid')
# Each familiar word family has (baseline, gain for reference context).
DISCOURSE_GROUPS = (
    (words('problem question example'), -0.13, 1.05),
    (words('problems questions examples'), -0.02, 0.80),
    (words('equation equations expression expressions theorem lemma '
           'inequality'), -0.22, 0.65),
    (words('description discussion statement statements analysis analyses '
           'paragraph subsection subparagraph'), -0.25, 0.85),
    (words('information conditions condition findings evidence constraints '
           'calculation setup'), -0.08, 0.65),
    (words('case cases code issue issues study studies sample model article '
           'text input data results result steps step argument thought review '
           'picture'), -0.025, 0.50),
    (words('method methods approach approaches formula section sections figure '
           'figures table tables requirement requirements exercise '
           'consideration definition graph'), 0.03, 0.50),
    (words('original initial proposed present existing early later'), -0.10, 0.50),
)
DISCOURSE = {word: (base, strength)
             for group, base, strength in DISCOURSE_GROUPS for word in group}
REPORTING = words('stated shown listed noted indicated specified outlined '
                  'cited referenced reported presented illustrated '
                  'provided seen '
                  'learned discussed')
PLURAL_CARDINALS = words('two three four five six seven eight nine ten')
COPULA = words('is are be was were being')
PERFECT = words("been have has had 've")
DISCOVERY = words('defined considered found identified established calculated')
PAST = words('previously already earlier before')
PREPOSITIONS = words('in from into with under according')
POSSESSIVE = words('my our your')
PERSONAL = words('i we you they he she')
REFERENTIAL = words('that those same following original initial proposed '
                    'present previous preceding given')
NUMBERS = words('first second third last next one two three four both all each')


REPORTS = {w: (0.17, 0.9) for w in REPORTING}
REPORTS.update({w: (0.1, 0.45) for w in DISCOVERY})
REPORTS.update(mentioned=(1.25, 1.4), described=(1.1, 1.0), discussed=(0.55, 1.2))


def cue(previous):
    """How explicitly the previous word selects already-identified material."""
    if previous in STRONG_REFERENCE or previous == 'above':
        return 3.0
    if previous in PAST:
        return 1.8
    if previous in POSSESSIVE:
        return 1.3
    if previous in {'this', 'these'}:
        return 1.2
    if previous in REFERENTIAL:
        return 1.2
    if previous == 'the':
        return 1.0
    if previous in PREPOSITIONS:
        return 0.6
    if previous in NUMBERS:
        return 0.4
    if previous in {'his', 'her', 'their', 'its'}:
        return 0.35
    if previous == 'of':
        return 0.2
    return 0.0


def activation(word, previous):
    if word in STRONG_REFERENCE:
        return -5.2
    if word in {'above', 'earlier'}:
        base, scale, cited = ((1.5, 3.6, 5.4) if word == 'above'
                              else (1.8, 1.5, 4.9))
        if previous in CITATION:
            return -cited
        context = cue(previous)
        if previous == 'as':
            context = 0.5 if word == 'above' else 0.8
        elif previous in REPORTING or previous in DISCOVERY:
            context = 0.6
        elif previous in DISCOURSE:
            context = 0.4
        elif previous in COPULA:
            context = -0.2
        elif previous in {'a', 'an'}:
            context = 0.0 if word == 'above' else -0.5
        return -base - scale * context
    if word in {'previous', 'preceding'}:
        return -0.65 - 1.3 * cue(previous)
    if word in {'previously', 'already', 'prior'}:
        if previous in CITATION:
            return -1.7
        if previous == 'as':
            return -1.1
        if previous in PERSONAL:
            return -0.9
        return -0.6 if previous in PERFECT else -0.25 - 0.8 * cue(previous)
    if word == 'given':
        if previous in COPULA or previous in {'a', 'an'}:
            return 0.15
        return -0.3 if previous in PERFECT else 0.05 - 1.9 * cue(previous)
    if word in {'said', 'says', 'mentions'}:
        if previous in {'i', 'we', 'you'}:
            return -1.1 if word == 'said' else -0.4
        return -0.25 - 1.3 * cue(previous)
    if word in REPORTS:
        base, strength = REPORTS[word]
        if previous in COPULA:
            return -0.3 * base
        context = cue(previous)
        if previous == 'as':
            context = 1.0
        elif previous in PERSONAL:
            context = 1.6 if word in {'mentioned', 'discussed'} else 0.6
        elif previous in PERFECT or previous in DISCOURSE:
            context = 0.3
        elif previous in PAST:
            context = 2.4
        return -base - strength * context
    if word in DISCOURSE:
        base, strength = DISCOURSE[word]
        if word == 'description':
            base, strength = -0.5, 0.8
        return base - strength * cue(previous)
    if word in {'here', 'herein', 'before', 'below'}:
        if previous in CITATION or previous == 'as':
            return -0.95
        return -0.09 - 0.6 * cue(previous)
    if word in PLURAL_CARDINALS:
        context = 1.6 if previous == 'these' else cue(previous)
        return 0.06 - 0.36 * context
    if word == 'these':
        return -0.04 - 0.5 * cue(previous)
    if word == 'following':
        return 0.19
    # Chinese backward pointers and their common split-token endings.
    if word in {'上述', '前述', '所述'}:
        return -5.7
    if word in {'以上', '上面'}:
        return -2.3
    if word in {'之前', '前面'}:
        return -0.9
    if word == '述' and previous.endswith(('上', '前')):
        return -5.4
    if word in {'выше', 'précédent'}:
        return -2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    # An unspaced fragment inside a word is not a separate discourse word.
    boundary = (not previous or raw[:1].isspace() or raw[:1].isupper()
                or not previous[-1:].isalpha()
                or any(ord(c) > 127 for c in word))
    value = activation(word, previous.strip().lower()) if boundary else 0.0
    if raw.lstrip()[:1].isupper():
        value *= 0.65
    if not previous:
        if word == 'above':
            value = -7.0
        elif word in {'earlier', 'mentioned', 'described'}:
            value = -3.2
        elif word == 'given':
            value = -2.0
    return (doc, raw), float(value)

programs.haiku:
"""Back-reference detector (layer-0 MLP output direction 5227).

The component writes a negative value on words that point back to text already written:
"the above", "as described", "as mentioned earlier", "the foregoing", "the previous step",
"the problem", "the given", "this equation", "the statement". It is most negative on explicit
pointers (STRONG words), less on nouns for an item already introduced (MEDIUM), and only
slightly on participles and similar words (WEAK). The value is strongest right after "the",
"as", "this" or "said" (a pointer to a specific earlier item), and near zero after "a"/"an"
("a problem" is not a pointer). Everything else is about zero.
"""

READS = ()

STRONG = {
    "above", "foregoing", "earlier", "aforementioned", "preceding", "previous",
    "previously", "mentioned", "described", "discussed", "outlined", "herein", "supra",
    "以上", "上述", "之前", "前述", "就是",
}
MEDIUM = {
    "problem", "question", "statement", "statements", "equation", "equations", "issue",
    "assumption", "findings", "analysis", "analyses", "paragraph", "lemma", "theorem",
    "proposition", "argument", "reasoning", "discussion", "description", "definition",
    "calculation", "expression", "cited", "listed", "specified", "encountered", "learned",
    "alleged", "suggestions", "assertion", "allegations", "elsewhere", "original",
    "already", "said", "given", "stated", "provided", "reported", "indicated", "mentions",
    "analyzed", "reviewed", "highlighted", "shown", "prior", "prompt", "latter",
}
WEAK = {"below", "case", "conditions", "condition", "example", "information", "data",
        "code", "existing", "initial", "ahead", "thereto", "subparagraph"}

POINTING = {"the", "as", "this", "that", "these", "those", "said", "my", "your", "our", "described", "mentioned", "stated", "discussed", "given", "shown", "statements", "statement", "above"}
INDEFINITE = {"a", "an", "any", "another"}

# activation written for (word tier, what precedes the word): pointing, other, indefinite
VALUES = {
    "STRONG": (-2.8, -1.7, -0.8),
    "MEDIUM": (-1.0, -0.3, -0.1),
    "WEAK": (-0.6, -0.1, 0.0),
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
        tier = "STRONG"
    elif word in MEDIUM:
        tier = "MEDIUM"
    elif word in WEAK:
        tier = "WEAK"
    else:
        return None, 0.0
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if before in POINTING:
        kind = 0
    elif before in INDEFINITE:
        kind = 2
    else:
        kind = 1
