"""A token-local negative lexical feature: strongest on ish, finish, and fish.

The suffix's inflections, sh-like fragments, and words about completion,
seafood, languages, and business give smaller responses. Arabic/Cyrillic
sh spellings and Chinese/Russian fish words are included. This is a coarse
word-family approximation, using case and word boundaries but no earlier
context; unrecognized tokens receive zero.
"""
READS = ()

ISH_SUFFIXES = {'ish': -4.5, 'ished': -3.4, 'ishing': -3.25,
                'ishes': -2.3, 'ishly': -2.1, 'ishment': -1.8}
SH_FRAGMENTS = {'sh': -1.0, 'esh': -1.0, 'ush': -1.3,
                'osh': -0.65, 'shire': -1.7, 'уш': -1.0, 'ش': -0.85}
LANGUAGES = {'english': -1.1, 'irish': -0.85, 'finnish': -1.0,
             'danish': -0.8, 'spanish': -0.45, 'polish': -0.55,
             'british': -0.35, 'persian': -1.2}
FOOD_AND_DRINK = {'drink', 'salmon', 'shrimp', 'dishes'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip().lstrip('._/-(=')
    word = text.lower()
    boundary = raw != text
    value = 0.0
    if word in ISH_SUFFIXES:
        value = ISH_SUFFIXES[word]
        if text.istitle():
            value *= 0.4
        elif raw.startswith('-'):
            value *= 0.6
    elif word in {'finish', 'finished', 'finishing', 'finishes'}:
        value = -4.0 if word == 'finished' else -4.5
        if word == 'finish':
            value = -5.3 if boundary else -4.5
    elif word == 'fish':
        value = -4.5 if boundary else -5.9
        if text != word:
            value = -4.0 if boundary else -4.5
    elif word.startswith('fish'):
        value = -2.8 if word == 'fishes' else -1.8
    elif word in {'inish', 'lish'}:
        value = -4.6
    elif word == 'dish':
        value = -1.3 if boundary else -2.9
    elif word in SH_FRAGMENTS:
        value = SH_FRAGMENTS[word]
        if word == 'sh' and (text != word or raw.startswith(('.', '_', '-'))):
            value = -0.5
        elif word == 'ش' and boundary:
            value = -0.3
    elif word.startswith('isch'):
        value = -0.7
    elif word in LANGUAGES:
        value = LANGUAGES[word]
    elif word.startswith(('accomplish', 'fulfil', 'establish', 'furnish')):
        value = -0.9
    elif word in {'completed', 'completing', 'completion'}:
        value = -0.85
    elif word == 'complete':
        value = -0.4
    elif word == 'done':
        value = -0.3 if boundary and text == word else -0.7
    elif word in FOOD_AND_DRINK or word in {'business', 'fashion'}:
        value = -1.0
    elif text in {'鱼', '魚', '捕鱼', 'рыб'}:
        value = -2.4
    elif text in {'完成', '渔'}:
        value = -1.3
    return None, value

