programs.sol:
"""A token-class approximation to a document-start pulse.

Reset on document labels, even if the row begins inside a word or sentence.
Digits, headings and source-file openers give the largest pulse. Whitespace
and space-prefixed words give smaller ones. A short tail has chat-header,
newline and number-continuation adjustments; other later tokens are near zero.
Lexical differences within these classes are deliberately omitted.
"""
READS = ()
DIGITS = (0.60, 0.87, 1.34, 1.13, 1.11,
          1.12, 1.07, 1.06, 0.89, 1.13)
ARTICLES = {'a', 'an', 'the'}
SENTENCE_OPENERS = {'A', 'An', 'The', 'This', 'I', 'We', 'You',
                    'What', 'How', 'In'}
FILE_OPENERS = {'import', 'package', '#include', '<?'}


def opening(s):
    if s.startswith('<|'):
        return 0.38
    if len(s) == 1 and s in '0123456789':
        return DIGITS[int(s)]
    if s in {'#', '##', 'Title'}:
        return 1.55
    if s == '###':
        return 0.92
    if s in FILE_OPENERS:
        return 0.88
    if s.startswith('/*'):
        return 0.70 if '\n' in s else 1.10
    if s.startswith('//'):
        return -0.10 if '\n' in s else 0.71
    if s.startswith('#!') or s == '-':
        return 0.70
    if s.isspace():
        if '\n' in s:
            return 0.29 / s.count('\n')
        return 0.36 if len(s) <= 2 else 0.25
    if s in SENTENCE_OPENERS:
        return 0.86
    word = s.strip()
    if s[0].isspace():
        if word.lower() in ARTICLES:
            return 0.46
        return 0.57 if word in {'of', 'by'} else 0.32
    if any('\u4e00' <= c <= '\u9fff' for c in s):
        return 0.28
    if any(ord(c) > 127 and c.isalpha() for c in s):
        return 0.36
    if s.isalpha():
        return 0.60 if len(s) == 1 and s.isupper() else 0.45
    if '\n' in s:
        return 0.23 if s.count('\n') == 1 else 0.13
    if s[0] in ')]}':
        return 0.21
    return 0.35


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    n = 0 if first else carry[1] + 1
    chat = s == '<|im_start|>' if first else carry[2]
    if first:
        value = opening(s)
    else:
        value = 0.07 * 0.45**(n - 1) if n < 9 else 0.0
    if not first:
        if chat and n == 1 and s in {'user', 'assistant', 'system'}:
            value = 0.13 if s == 'user' else 0.32
        elif chat and n == 2 and s == '\n':
            value = -0.11
        elif s.isspace() and '\n' in s:
            if n == 1:
                value = 0.025
            else:
                value = -0.015 if n < 9 else -0.006
        elif len(s) == 1 and s in '0123456789':
            value = 0.15 if n == 1 else value - 0.004
    return (doc, n, chat), float(value)

"""Approximate negative responses to control flow and low-level input/output.

Loops, conditionals, C I/O, and console/file operations are the main signals.
Indentation, statement boundaries, and escaped newlines strengthen control
words relative to prose. Related library operations share one strength.
Strengths are rough training averages; small responses elsewhere are ignored.
Unrecognized text gets zero. This is a lexical/syntax heuristic, not a parser.
"""
import re

READS: tuple[str, ...] = ()

# (spaced prose, unspaced word, executable statement)
CONTROL = {
    'for': (-0.03, -0.75, -2.4),
    'if': (-0.03, -0.2, -1.4),
    'while': (-0.3, -1.0, -3.25),
    'else': (-0.12, -0.65, -1.13),
    'elif': (-0.5, -1.1, -1.03),
    'foreach': (-1.2, -1.3, -1.5),
    'continue': (-0.04, -0.3, -1.65),
    'break': (0.0, -0.3, -1.5),
    'switch': (-0.09, -0.5, -1.3),
    'goto': (-0.75, -0.75, -1.0),
    'try': (-0.15, -0.45, -0.9),
    'except': (-0.02, -0.1, -0.78),
    'catch': (-0.13, -0.4, -0.7),
    'finally': (0.04, -0.4, -0.78),
    'return': (0.33, 0.35, -0.25),
    'do': (0.02, -0.2, -0.75),
    'print': (-0.05, -0.15, -0.52),
    'assert': (0.0, -0.08, -0.53),
    'raise': (-0.12, -0.1, -0.6),
    'exit': (-0.35, -0.4, -1.25),
}
C_FILE_IO = set(
    'fopen fclose freopen fread fwrite fgets feof fflush getline'.split()
)
C_MEMORY = set('strcpy strcmp memset memcpy malloc calloc realloc'.split())
C_UTILITIES = set(
    'atoi atof getch chmod htons htonl strerror errno sizeof'.split()
)
C_HEADERS = set(
    'stdio stdlib cstdlib iostream ostream ofstream unistd pthread cmath'.split()
)
METHOD_IO = {
    'Printf': -2.0, 'Sprintf': -1.25, 'Errorf': -0.65,
    'Println': -0.63, 'WriteLine': -1.15, 'ReadLine': -1.85,
    'printStackTrace': -1.3, 'readFileSync': -1.7,
    'readline': -1.9, 'nextLine': -1.6, 'InputStreamReader': -1.7,
    'close': -1.05, 'readlines': -1.1, 'sleep': -1.3,
    'mkdir': -1.1, 'chdir': -1.6, 'recv': -0.8,
    'printf': -1.1, 'println': -0.13, 'out': -1.1,
}
SMALL = {
    'echo': -0.45, 'grep': -0.4, 'def': -0.4,
    '#include': -0.4, 'Import': -0.53, 'typedef': -1.0,
    'For': -0.33, 'While': -0.29, 'If': -0.07,
    'endl': -0.7, 'EOF': -0.65,
}
CODE = re.compile(
    r'[={}\[\]]|\b(?:int|def|func|void|var|let|const|with|assert|return)\b'
)


def control_value(word, token, previous, recent, line):
    prose, bare, statement = CONTROL[word]
    spaced = token[:1].isspace()
    value = prose if spaced else bare
    escaped = recent.endswith(('\\n', '\\t'))
    if (not spaced and token[:1].isalpha() and previous
            and previous[-1].isalpha() and not escaped):
        return 0.0
    indent = previous.isspace() and '\n' not in previous
    separator = previous.rstrip().endswith((';', '{', '}', ':'))
    if '\t' in token or indent:
        factor = 0.75 if '\t' in previous and '\t' not in token else 1.0
        value = factor * statement
    elif escaped:
        value = 0.55 * statement
    elif recent.endswith('\n'):
        factor = 1.0 if separator or previous.rstrip().endswith(')') else 0.7
        value = factor * statement
    elif separator:
        value = (0.8 if CODE.search(line) else 0.25) * statement
    elif previous.strip() in ('`', '``', '```', '#', '//'):
        value = (0.4 if spaced else 0.8) * statement
    if word == 'for' and spaced and not indent and not separator:
        if line.count('[') > line.count(']'):
            value = -1.2
        elif CODE.search(line) and re.search(r'\w+\(', line):
            value = -0.7
    if word == 'exit' and CODE.search(line):
        value = min(value, -0.75)
    if word == 'if' and previous.strip() == 'else':
        value = -1.1
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous = '', ''
    else:
        _, recent, previous = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.lstrip('._(#}+-<')
    line = re.split(r'\n|\\n', recent)[-1]
    member = stripped.startswith(('.', '_'))
    value = 0.0
    if word in CONTROL:
        value = control_value(word, token, previous, recent, line)
    elif word in METHOD_IO and (member or word[0].isupper()):
        value = METHOD_IO[word]
    elif word in ('scanf', 'sscanf', 'fscanf'):
        value = -5.3
    elif word in ('printf', 'fprintf', 'sprintf', 'perror'):
        value = -4.0 if word == 'fprintf' else -2.9
    elif word in C_FILE_IO:
        value = -3.3
    elif word in C_MEMORY:
        value = -2.0
    elif word in C_UTILITIES or word in C_HEADERS:
        value = -1.6
    elif word in ('cout', 'cin', 'cerr'):
        code = CODE.search(line) or re.search(r'\bcout\b|<<|>>', line)
        value = -2.6 if word != 'cin' else (-4.2 if code else -0.65)
        if '\t' in token:
            value = -4.2 if word == 'cin' else -3.25
        if (token[:1].isalpha() and previous
                and previous[-1].isalpha()):
            value = -0.4
        if word == 'cerr' and not code:
            value = -0.7
    elif word in ('stdin', 'stdout', 'stderr'):
        value = -0.3 if member else -0.6
        if stripped.startswith('('):
            value = {'stdin': -2.7, 'stdout': -1.7, 'stderr': -2.15}[word]
    elif word == 'import':
        value = -0.45 if token.startswith(' ') else -0.92
        if not recent and not token.startswith(' '):
            value = -1.38
    elif word == 'main':
        value = -2.3 if previous.strip() == 'int' else -0.6
        if previous.strip() in ('def', 'func', 'void', 'fn'):
            value = -1.3
    elif word == 'open':
        value = -1.7 if previous.strip() == 'with' else -0.4
    elif word in SMALL or token in SMALL:
        value = SMALL.get(word, SMALL.get(token, 0.0))
        if word in ('For', 'While', 'If') and not token[:1].isspace():
            value *= 1.65
    elif word in ('system', 'free', 'puts') and CODE.search(recent):
        if '\t' in token or previous.isspace():
            value = -1.6
    elif token.endswith('"%'):
        value = -3.5 if previous.strip().endswith('scanf') else -0.8
    elif stripped == '>>' and previous.strip().endswith('cin'):
        value = -1.6
    return (doc, (recent + token)[-240:], token), float(value)

programs.luna:
"""A small lexical approximation to a rare visual-media and promotion cue.

Strong harvested responses include photo/video/image words and design or
art terms; other responses mention publishing and promotional material. The
program follows a word across split tokens, then predicts a negative pulse for
those terms, with a smaller pulse for the broader publishing vocabulary.
"""
READS = ()

VISUAL_MEDIA = frozenset({
    "photo", "photos", "photograph", "photographs", "photography",
    "foto", "fotoğraf", "image", "images", "picture", "pictures",
    "video", "videos", "film", "films", "movie", "movies",
    "visual", "visuals", "art", "artwork", "illustration",
    "illustrations", "graphic", "graphics", "logo", "logos", "artist", "artists",
    "banner", "banners", "poster", "posters", "sign", "signs",
    "montage", "gallery", "design", "decor", "décor", "artistic",
    "creative", "background", "backgrounds", "图片", "照片", "圖片",
    "视频", "影片", "視頻", "二维码", "企画", "画",
})
PUBLISHING = frozenset({
    "blog", "page", "pages", "cover", "editorial", "刊物",
    "billboard", "card", "cards", "keyword", "keywords", "phrase",
    "content", "contents", "campaign", "ad", "ads", "advert",
    "advertising", "marketing", "promotion", "promotional", "leaflet",
    "leaflets", "行銷", "内容", "內容",
})


def _letter(char):
    return char.isalnum() or char in "\u0300\u0301\u0308\u0327"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    piece = prefix.token_strings[-1]
    exact = piece.strip().lower()
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    end = len(piece)
    while end and _letter(piece[end - 1]):
        end -= 1
    tail = piece[end:]
    if exact in VISUAL_MEDIA or exact in PUBLISHING:
        word = exact
    elif not tail:
        word = ""
    elif end == 0:
        word = previous + tail
    else:
        word = tail
    word = word.lower()
    if word in VISUAL_MEDIA:
        value = -0.65
    elif word in PUBLISHING:
        value = -0.38
    else:
        value = 0.0
    return (doc, word if word else ""), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:5234.

It reads the word right after a quantity word, and its sign says what kind of phrase
that word starts:

  * after "some" + a vague, idiomatic noun ("some kind", "some sort", "some form",
    "some way", "some point", "for some reason"): strongly negative, about -3.5;
    after "any" or "no" + the same nouns ("any way", "no way", "no reason"): about -2;
  * after "some" + a phrase that goes on with "of", "more", "people", "examples"
    ("some of", "some more"): positive, about +1.8 to +3.5; after "any" / "no" + "more",
    "further", "longer": about +2;
  * after "some" / "any" / "no" + a plural noun ("some tests", "any problems"): mildly
    positive, about +0.5;
  * after the weaker quantities "few", "little", "bit", "many", "several", "most",
    "nothing" + "more" or "of": mildly positive, about +0.3 to +1.6;
  * on "of" right after "sort", "kind", "type" or "form" ("sort of", "kind of"):
    mildly negative.

Everything else is treated as zero. Only the previous and current word are read.
What it leaves out: most of the variance is small, diffuse activity on ordinary words,
and singular abstract nouns after "some" ("some idea", "some effect"), which are also
negative but are not listed here.
"""

SOME = {"some"}
ANY_NO = {"any", "no"}
WEAK = {"few", "little", "bit", "many", "several", "most", "nothing", "couple"}
HEDGE_NOUN = {"kind", "sort", "form", "type", "way", "point", "reason", "such", "one",
              "question", "sense", "time", "day"}
CONTINUE = {"of", "more", "further", "people", "examples", "things", "very", "longer",
            "anymore", "questions", "years", "days", "minutes"}
HEDGE_OF = {"sort": -1.1, "kind": -0.7, "type": -0.3, "form": -0.2}

READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    before = prefix.token_strings[-2].strip().lower()
    word = prefix.token_strings[-1].strip().lower()
    if before in SOME:
        if word in HEDGE_NOUN:
            return carry, -3.5
        if word in CONTINUE:
            return carry, 3.0 if word == "more" else 1.8
        if word.endswith("s") and len(word) > 3:
            return carry, 0.5
    elif before in ANY_NO:
        if word in HEDGE_NOUN:
            return carry, -2.0
        if word in CONTINUE and word != "of":
            return carry, 2.0
        if word.endswith("s") and len(word) > 3:
            return carry, 0.5
    elif before in WEAK and word in CONTINUE:
        return carry, 1.0
    if word == "of" and before in HEDGE_OF:
        return carry, HEDGE_OF[before]
    return carry, 0.0

