"""Approximate this component using only the current token's text.

The main rules assign negative values to fused grammatical fragments: Chinese
function words plus short word beginnings, Japanese particles plus stems or
polite endings, and Arabic article prefixes. Korean predicate endings, English
contraction stems and some code-boundary shapes have smaller rules. Structural
markers have separate values, especially positive </think>.

These are family-level heuristics, not a general word segmenter. They omit
lexical exceptions and context; their strengths are calibrated on training data.
"""
READS = ()

# (Mandarin grammatical prefix, fragment multiplier, longer-phrase value)
CHINESE_STARTS = (
    ('的', 1.00, -0.90),                 # possession/modification
    ('了', 0.84, -1.06),                 # aspect
    ('是', 0.78, -0.86),                 # copula
    ('有', 0.62, -0.48),                 # existence
    ('在', 0.94, -0.68),                 # location
    ('就也都而还還', 0.57, -0.60),       # connective adverbs
    ('为為得将將给給让讓把', 0.61, -0.75), # grammatical verbs
    ('我你他她您', 0.20, 0.0),           # personal pronouns
    ('和与與或并並', 0.21, -1.20),       # conjunctions
    ('对對从從用向跟以', 0.36, -0.85),   # relational words
    ('中上下', 0.22, -0.25),               # spatial relations
    ('个個', 0.29, -0.30),               # classifier
)
# Following-word beginnings grouped by meaning, not token identity.
CHINESE_ENDS = (
    ('一几幾两兩', 4.92),                 # numerals
    ('不没沒', 5.07),                     # negation
    ('很太最多', 5.26),                   # degree/quantity
    ('大小', 3.57),                       # size
    ('好新老', 3.03),
    ('心情', 2.63),      # qualities, mental states
    ('手眼头頭口脸臉身', 2.70),           # body parts
    ('人我你他她其您', 1.75),             # people/pronouns
    ('这那這', 2.31),                     # demonstratives
    ('是了的到过過为為和与與而但也就有能要以於于會会们們', 0.23),
)
JAPANESE_PARTICLES = set('をにのがではとも')
JAPANESE_POSTPOSITIONS = {
    'について', 'によって', 'にとって',
    'において', 'のために', 'のように',
}


def han(c):
    return '\u4e00' <= c <= '\u9fff'


def chinese(s):
    if len(s) == 1:
        return -1.03 if s == '吧' else -0.53 if s in '呢哪吗嗎' else 0.0
    pair = s[-2:]
    for chars, strength, phrase in CHINESE_STARTS:
        if pair[0] in chars and (len(s) == 2 or pair[0] in '的了也都'):
            onset = next((v for cs, v in CHINESE_ENDS if pair[1] in cs), 0.84)
            if pair[1] == '有':
                onset = 2.7 if pair[0] == '是' else 1.15
            scale = 0.85
            if len(s) > 2 and pair[0] == '的' and pair[1] in '很太最多':
                scale = 0.45
            return -strength * onset * (scale if len(s) > 2 else 1.0)
    for chars, strength, phrase in CHINESE_STARTS:
        if s[0] in chars:
            return -2.1 if s[0] == '的' and s[1] == '第' else phrase
    conjunctions = ('如果', '所以', '然后', '然後', '或者', '以及')
    if len(s) > 2 and s.startswith(conjunctions):
        return -3.0 if s[-1] in '不没沒' else -1.2
    return -0.03


def japanese(s):
    if len(s) == 1:
        if s == 'お':
            return -1.30
        if s in JAPANESE_PARTICLES or s in 'やく':
            return 0.12
        return -0.4 if s in 'いしなまだ' else -0.08
    if s in ('とても', 'もっと'):
        return 0.5  # degree adverbs, not particle + word fragments
    if s == 'という':
        return -0.36
    if s == 'として':
        return 0.48
    if s in JAPANESE_POSTPOSITIONS:
        return 0.0
    if len(s) == 2 and s[0] in JAPANESE_PARTICLES:
        if s[1] in 'おご':
            honorific_gain = {
                'を': 6.34,
                'に': 5.23,
                'の': 3.62,
                'で': 5.36,
            }
            gain = honorific_gain.get(s[0], 4.5)
            return -gain * (0.79 if s[1] == 'ご' else 1.0)
        if han(s[1]):
            return -3.5 if s[1] in '一大小' else -2.6
