        return chinese(s)
    if any('\u3040' <= c <= '\u309f' for c in s):
        return japanese(s)
    if any('\u0600' <= c <= '\u06ff' for c in s):
        if s.startswith(('وال', 'بال', 'لل')):
            tail = s[3:] if s.startswith(('وال', 'بال')) else s[2:]
