    # A single scale fitted on training activations; no context/state is read.
    return None, float(0.95 * activation(prefix.token_strings[-1]))

"""Approximate a code-to-explanation boundary signal.

Closing blocks, comments, strings, HTML tags and Markdown fences are negative;
line-leading `if` is positive. English exposition starters are more negative
when the preceding line looks like code. Split backtick fences and their next
two token positions need a little state. A line ending in `assistant` is
a reply-start cue for some transitions. Everything else is near zero. Line margins may
include indentation, a diff marker or a displayed source line number.
"""
import re

READS = ()
MARGIN = re.compile(r"[ \t]*(?:[+*-][ \t]*)?(?:\d+[ \t]+)?$")
TRANSITIONS = {"So", "Thus", "Therefore", "Then", "Now", "And"}
INTRODUCTIONS = {"Here", "Answer", "Output", "Make"}
REFERENCES = {"This", "These", "It", "Your"}
EXPOSITION = TRANSITIONS | INTRODUCTIONS | REFERENCES | {
    "I", "We", "You", "The", "In", "What", "But"
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, "", "", "", 0, 0)
    _, line, last_line, previous, ticks, after_fence = carry
    s = prefix.token_strings[-1]
    word = s.strip()
    margin = bool(MARGIN.fullmatch(line))
    space, newline = s.startswith(" "), "\n" in s
    brace = "}" in last_line
    code = brace or last_line.rstrip().endswith((")", ";", ">", "]"))
    intro = last_line.rstrip().endswith(":")
    value = 0.0

    if word.startswith("}") and not word.strip("}]),;:\\`(.*"):
        value = -0.20 if space else 0.0
        if newline:
            value = -0.45 if space else -0.25
        if margin:
            value = -0.78
        if word.endswith("`"):
            value -= 0.65
    elif word.startswith("*/") or word in ('"""', "'''") and newline:
        value = -0.78
    elif word.startswith("]") and space and margin:
        value = -0.85
    elif word.startswith(")") and space and newline:
        value = -0.4
    elif word == "</":
        value = -0.65 if margin else -0.06
    elif previous.strip() == "</" and word.isalpha():
        value = -1.5 if word in {"code", "pre"} else -0.65
    elif word.startswith(">") and re.search(r"</[\w-]+$", line):
        value = -0.65 if newline else -0.35
        if line.endswith(("</code", "</pre")):
            value -= 0.5
    elif word == "if" and margin:
        value = 0.48 if space else 0.23 if s.startswith("\t") else 0.18
    elif word == "return":
        value = -0.65 if margin else -0.13
        if margin and any(c in last_line for c in "}]"):
            value -= 0.24
    elif word == "end" and margin:
        value = -0.45
    elif margin and word in EXPOSITION:
        if word in INTRODUCTIONS:
            value = -0.65
        elif word in REFERENCES:
            value = -0.2
        if word in TRANSITIONS:
            value = -0.8 if last_line.endswith("assistant") else -0.28
        if code:
            value -= 0.33

    backticks = "`" in word and not word.strip("`\\")
    if backticks:
        count = word.count("`")
        if (newline or s.endswith("\\")) and ticks >= 2:
            value = -2.1
            if s.count("\n") >= 2:
                value = -3.2 - 0.6 * code - 0.3 * brace
            if not MARGIN.fullmatch(line.rstrip("`")) and s.count("\n") >= 2:
                value = -3.2
            elif s.count("\n") < 2 and intro:
                value = -0.65
        elif newline and count >= 3:
            value = -2.0
        elif margin and count >= 2:
            value = -0.4 if intro else -1.3 - 1.0 * code - 0.5 * brace
            if count >= 3 and not brace:
                value += 0.7
        elif (ticks and s.startswith("`")) or (count >= 2 and
                line.rstrip().endswith((";", ")", "}"))):
            value = -0.8
    elif word and not word.strip("~") and (len(word) > 1 or newline):
        value = -0.75
    elif after_fence == 1 and word in {"This", "These", "In", "With", "The"}:
        value = -2.0
        if word in {"This", "These"}:
            value = -3.1
        elif word == "The":
            value = -1.0
    elif after_fence == 2 and word in {"this", "these"}:
        value = -2.3
    if s.isspace() and newline and ticks >= 3:
        value = -1.8

    # Join only the pending ticks, not the whole prefix, to spot split fences.
    joined = "`" * ticks + s
    fence_ended = bool(re.search(r"`{3,}\r?\n", joined))
    tail = joined.rstrip("\r")
    ticks = min(8, len(tail) - len(tail.rstrip("`")))
    lines = (line + s).split("\n")
    completed = [text for text in lines[:-1] if text.strip()]
    if completed:
        last_line = completed[-1][-120:]
    line = lines[-1][-120:]
    if fence_ended:
        after_fence = 1
    elif after_fence:
        after_fence = min(after_fence + 1, 4)
    return (doc, line, last_line, s, ticks, after_fence), float(value)

