        if raw != raw.lstrip('_.(/-'):
            return -6.3
        if token[:1].isspace() or raw == 'Pass':
            return -6.9
        return -5.8
    if word in {'passed', 'passing', 'passes'}:
        return -5.9 if raw.islower() else -5.5
    if word == 'pas':
        return -2.05 if raw.islower() else -2.45
    if word in {'passage', 'passages', 'passer'}:
        return -2.9
    if word in {'passe', 'passé', 'paso', 'pasado', 'pasar', 'pasa'}:
        return -2.25
    if word in {'bypass', 'ypass'}:
        return -2.4
    if word == 'past':
        return -1.8 if raw.islower() else -1.5
    if word in {'password', 'passwords'}:
        return -1.6
    if word in {'passenger', 'passengers', 'passport', 'passports'}:
        return -1.1
    if word == 'passive':
        return -1.6
    if word.startswith('surpass') or word == 'trespass':
        return -1.3
    if word.startswith(('passion', 'pastor', 'paste')):
        return -0.5
    if word in {'fail', 'failed', 'failing', 'fails'}:
        if raw == 'FAILED' or word == 'fails':
            return -1.15
        return -1.65
    if word in {'failure', 'failures'}:
        return -0.5
    if word in {'filtration', 'exceeding', 'exceeded'}:
        return -0.8
    if word == 'filtered':
        return -0.48
    if word in {'过', '過'}:
        return -3.2
    if word in PAST_WORDS:
        return -2.15
    if word in PASSING_WORDS:
        return -1.4
    if word == '传递':
        return -2.5
    if word in ARRIVAL_OR_TRANSMISSION:
        return -0.95
    if '过' in word or '過' in word:
        return -0.9
    if word in {'失败', '过滤'}:
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = lexical_value(token)
    # A word ending may be a separate token rather than part of PASS.
    if previous.strip().lower() in {'pass', 'pas'} and token.isalpha():
        ending = token.lower()
