            value = -1.8 if ending == 'sed' else -4.7
        elif ending in {'age', 'ages', 'er', 'o', 'ag'}:
            value = -2.7
        elif ending in {'ar', 'a', 'ando', 'ado', 'ato', 'ada', 'agem'}:
            value = -1.8
        elif ending in {'en', 'ant', 'able', 'iert', 'os', 'èrent', 'ung'}:
            value = -0.85
    return (doc, token), float(value)

