RESTART_WORDS = {"再", "又", "而"}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    now, before = prefix.token_strings[-1], prefix.token_strings[-2]
