"""Approximate an initial-i spelling response, not a semantic topic detector.

Words, initials and variables beginning with i/I respond strongly; i-leading
word endings respond weakly. Case, length and following letters modulate the
response. Common grammatical words are exceptions: 'in' is nearly inactive,
while 'it' and 'if' respond. Punctuation and line starts strengthen some of
these short forms. Cyrillic и, Japanese い/イ, Korean 이, and a few spellings
of the pronoun 'I' have related responses. No token-ID lookup is used.
"""
import unicodedata

READS = ()
SEPARATORS = ' \t\r\n.,_-:/(\\\"\'`[{<>=+!;“”‘’'


def activation(token, previous, line_start):
    word = token.lstrip(SEPARATORS)
    if not word:
        return 0.0
    own_boundary = word != token
    spaced = token.startswith(' ')
    first = 'I' if word[0] == 'İ' else word[0]
