        return 1.75 if len(word) == 1 else 0.65
    if first in 'иИ':
        if not boundary:
            return 0.15
        value = 1.1 if len(word) <= 2 else 0.6
        return value + (0.65 if first == 'И' else 0.0)
    if first == '이':
        return 0.65 if own_boundary else 0.25
    if word == '我' or (word == 'я' and boundary):
        return 0.55
    if first not in 'iI':
        return 0.0

    # A script change or a capital inside camelCase can begin a Latin word.
    if previous.isalpha():
        boundary |= not unicodedata.name(previous, '').startswith('LATIN')
    if not boundary:
        return 0.1 if len(word) <= 3 else 0.03
