        if low == 'in' and not own_boundary and not upper:
            return 0.2
        return -0.03
    if low == 'is' and not word.isupper():
        if not spaced or upper:
            return 0.8
        if line_start:
            return 0.3
        if previous.isalpha():
            return 0.03
        return 0.21 if previous == ',' else 0.12
    if low in {'its', 'itself'}:
        return 0.12
    if low == 'it' and not word.isupper():
        if not spaced:
            return 1.35
        return 1.1 if upper else 0.72 if previous.isalpha() else 0.93
    if low == 'if':
        if not spaced:
            return 0.86 if upper or token.startswith('\t') else 0.96
        if upper or line_start:
            return 0.69
        return 0.5 if previous.isalpha() else 0.62

    if len(word) == 1:
        if not own_boundary or line_start:
            return 1.65
        if spaced:
            value = 1.04 if upper else 1.22
            return value + (0.32 if not previous.isalpha() else 0.0)
        return 1.23 if upper else 1.3
    if set(low) == {'i'}:
        return 0.65  # Repeated-I Roman numerals, II, III, ...
    if low == 'ich':
        return 1.6  # German first-person pronoun.
    if len(word) == 2:
        if low == 'id':
            return 1.7  # Identifier abbreviation.
        if low == 'il' and not word.isupper():
            return 1.0 + 0.25 * upper
        if low[1] in 'bcgopvx':
