programs.luna:
"""Predict the end-marker pulse and contextual uses of “of.”

The rule gives a positive pulse after cause/substitution cues, percentages,
partitive/support words, and words ending in “-ed” (often participles).
Other “of” tokens receive a small negative default; everything else is zero.
"""
READS = ()


OF_CUES = {"because", "instead", "support", "parts", "means", "%"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|endoftext|>":
        return None, 1.94
    if token == " of":
        previous = ""
        if len(prefix.token_strings) > 1:
            previous = prefix.token_strings[-2].strip().lower()
        if previous in OF_CUES or previous.endswith("ed"):
            return None, 1.5
        return None, -0.32
    return None, 0.0
